1	import { useState, useMemo } from "react";
2	import {
3	  useListRichTasks,
4	  useCreateRichTask,
5	  useUpdateRichTask,
6	  useDeleteRichTask,
7	  useListProjectUsers,
8	  getListRichTasksQueryKey,
9	} from "@/hooks/use-collaboration";
10	import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
11	import { Button } from "@/components/ui/button";
12	import { Input } from "@/components/ui/input";
13	import { Textarea } from "@/components/ui/textarea";
14	import { Skeleton } from "@/components/ui/skeleton";
15	import { Label } from "@/components/ui/label";
16	import { Badge } from "@/components/ui/badge";
17	import {
18	  Plus, Edit2, Trash2, CheckSquare, MoreHorizontal, X, CalendarDays,
19	  Table as TableIcon, Columns3,
20	  Check, XCircle,
21	} from "lucide-react";
22	import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
23	import { useQueryClient } from "@tanstack/react-query";
24	import { TaskCard } from "./task-card";
25	import { TaskDetailDrawer } from "./task-detail-drawer";
26	import { TaskFiltersBar } from "./task-filters";
27	import {
28	  STATUS_LABELS,
29	  STATUS_COLORS,
30	  PRIORITY_COLORS,
31	  type RichTask,
32	  type TaskFilter,
33	  type TaskSort,
34	  type TaskStatus,
35	} from "@/lib/collaboration-types";
36	import { format, isSameDay, startOfMonth, endOfMonth, eachDayOfInterval, isToday } from "date-fns";
37	
38	interface TasksProps {
39	  projectId: number;
40	}
41	
42	type ViewMode = "kanban" | "table" | "calendar";
43	
44	const COLUMNS: { id: TaskStatus; label: string }[] = [
45	  { id: "backlog", label: "Backlog" },
46	  { id: "in_progress", label: "In Progress" },
47	  { id: "review", label: "Review" },
48	  { id: "blocked", label: "Blocked" },
49	  { id: "done", label: "Done" },
50	];
51	
52	export function Tasks({ projectId }: TasksProps) {
53	  const qc = useQueryClient();
54	  const [view, setView] = useState<ViewMode>("kanban");
55	  const [filter, setFilter] = useState<TaskFilter>({});
56	  const [sort, setSort] = useState<TaskSort>({ field: "createdAt", direction: "desc" });
57	  const [selectedTasks, setSelectedTasks] = useState<Set<number>>(new Set());
58	  const [detailTask, setDetailTask] = useState<RichTask | null>(null);
59	  const [showAdd, setShowAdd] = useState(false);
60	  const [formData, setFormData] = useState({ title: "", description: "", status: "backlog" as TaskStatus });
61	
62	  const { data: tasks, isLoading } = useListRichTasks(projectId, filter, sort);
63	  const { data: users } = useListProjectUsers(projectId);
64	  const createTask = useCreateRichTask();
65	  const updateTask = useUpdateRichTask();
66	  const deleteTask = useDeleteRichTask();
67	
68	  const allTags = useMemo(() => {
69	    const tags = new Set<string>();
70	    tasks?.forEach((t) => t.tags.forEach((tag) => tags.add(tag)));
71	    return Array.from(tags);
72	  }, [tasks]);
73	
74	  const assigneeOptions = useMemo(() => {
75	    return (users ?? []).map((u) => ({
76	      id: u.id,
77	      name: [u.firstName, u.lastName].filter(Boolean).join(" ") || u.email || `User ${u.id}`,
78	    }));
79	  }, [users]);
80	
81	  const handleCreate = async () => {
82	    if (!formData.title) return;
83	    await createTask.mutateAsync({ projectId, data: formData });
84	    setShowAdd(false);
85	    setFormData({ title: "", description: "", status: "backlog" });
86	    qc.invalidateQueries({ queryKey: getListRichTasksQueryKey(projectId) });
87	  };
88	
89	  const handleBulkDelete = async () => {
90	    if (!confirm(`Delete ${selectedTasks.size} tasks?`)) return;
91	    for (const id of selectedTasks) {
92	      await deleteTask.mutateAsync({ projectId, taskId: id });
93	    }
94	    setSelectedTasks(new Set());
95	    qc.invalidateQueries({ queryKey: getListRichTasksQueryKey(projectId) });
96	  };
97	
98	  const handleBulkStatus = async (status: TaskStatus) => {
99	    for (const id of selectedTasks) {
100	      await updateTask.mutateAsync({ projectId, taskId: id, data: { status } });
101	    }
102	    setSelectedTasks(new Set());
103	    qc.invalidateQueries({ queryKey: getListRichTasksQueryKey(projectId) });
104	  };
105	
106	  const toggleSelect = (id: number) => {
107	    const next = new Set(selectedTasks);
108	    if (next.has(id)) next.delete(id);
109	    else next.add(id);
110	    setSelectedTasks(next);
111	  };
112	
113	  const selectAll = () => {
114	    if (!tasks) return;
115	    const allIds = tasks.map((t) => t.id);
116	    const allSelected = allIds.every((id) => selectedTasks.has(id));
117	    setSelectedTasks(new Set(allSelected ? [] : allIds));
118	  };
119	
120	  const groupedTasks = useMemo(() => {
121	    return COLUMNS.reduce((acc, col) => {
122	      acc[col.id] = tasks?.filter((t) => t.status === col.id) ?? [];
123	      return acc;
124	    }, {} as Record<TaskStatus, RichTask[]>);
125	  }, [tasks]);
126	
127	  const calendarDays = useMemo(() => {
128	    const now = new Date();
129	    return eachDayOfInterval({ start: startOfMonth(now), end: endOfMonth(now) });
130	  }, []);
131	
132	  return (
133	    <div className="h-full flex flex-col pb-8">
134	      <div className="flex flex-col gap-3 mb-4">
135	        <div className="flex justify-between items-center">
136	          <div className="flex items-center gap-2">
137	            <h2 className="text-xl font-bold">Project Tasks</h2>
138	            {tasks && <Badge variant="secondary" className="text-xs">{tasks.length} total</Badge>}
139	          </div>
140	          <div className="flex items-center gap-2">
141	            <div className="flex items-center border rounded-md overflow-hidden">
142	              <Button
143	                variant={view === "kanban" ? "secondary" : "ghost"}
144	                size="sm"
145	                className="rounded-none h-8 px-2"
146	                onClick={() => setView("kanban")}
147	              >
148	                <Columns3 className="h-4 w-4" />
149	              </Button>
150	              <Button
151	                variant={view === "table" ? "secondary" : "ghost"}
152	                size="sm"
153	                className="rounded-none h-8 px-2"
154	                onClick={() => setView("table")}
155	              >
156	                <TableIcon className="h-4 w-4" />
157	              </Button>
158	              <Button
159	                variant={view === "calendar" ? "secondary" : "ghost"}
160	                size="sm"
161	                className="rounded-none h-8 px-2"
162	                onClick={() => setView("calendar")}
163	              >
164	                <CalendarDays className="h-4 w-4" />
165	              </Button>
166	            </div>
167	            {!showAdd && (
168	              <Button onClick={() => setShowAdd(true)} size="sm" data-testid="add-task-button">
169	                <Plus className="h-4 w-4 mr-1" /> Add Task
170	              </Button>
171	            )}
172	          </div>
173	        </div>
174	
175	        <TaskFiltersBar
176	          filter={filter}
177	          onFilterChange={setFilter}
178	          sort={sort}
179	          onSortChange={setSort}
180	          availableTags={allTags}
181	          availableAssignees={assigneeOptions}
182	        />
183	
184	        {selectedTasks.size > 0 && (
185	          <div className="flex items-center gap-2 bg-muted/50 p-2 rounded-md">
186	            <span className="text-xs text-muted-foreground">{selectedTasks.size} selected</span>
187	            <Button size="sm" variant="ghost" className="h-7 text-xs" onClick={selectAll}>
188	              {tasks && tasks.length > 0 && selectedTasks.size === tasks.length ? "Deselect all" : "Select all"}
189	            </Button>
190	            <div className="flex-1" />
191	            <div className="flex items-center gap-1">
192	              {COLUMNS.map((col) => (
193	                <Button
194	                  key={col.id}
195	                  size="sm"
196	                  variant="ghost"
197	                  className="h-7 text-[10px] px-2"
198	                  onClick={() => handleBulkStatus(col.id)}
199	                >
200	                  Move to {col.label}
201	                </Button>
202	              ))}
203	              <Button
204	                size="sm"
205	                variant="ghost"
206	                className="h-7 text-xs text-destructive hover:text-destructive"
207	                onClick={handleBulkDelete}
208	              >
209	                <Trash2 className="h-3.5 w-3.5 mr-1" /> Delete
210	              </Button>
211	              <Button
212	                size="sm"
213	                variant="ghost"
214	                className="h-7 text-xs"
215	                onClick={() => setSelectedTasks(new Set())}
216	              >
217	                <XCircle className="h-3.5 w-3.5 mr-1" /> Cancel
218	              </Button>
219	            </div>
220	          </div>
221	        )}
222	      </div>
223	
224	      {showAdd && (
225	        <Card className="bg-card border-primary/40 mb-4" data-testid="task-form-panel">
226	          <CardHeader className="pb-3 flex flex-row items-center justify-between space-y-0">
227	            <CardTitle className="text-base">Add Task</CardTitle>
228	            <Button variant="ghost" size="icon" className="h-8 w-8" onClick={() => setShowAdd(false)}><X className="h-4 w-4" /></Button>
229	          </CardHeader>
230	          <CardContent className="space-y-3">
231	            <div className="space-y-1"><Label>Title *</Label><Input value={formData.title} onChange={(e) => setFormData({ ...formData, title: e.target.value })} placeholder="e.g. Design combat icons" autoFocus /></div>
232	            <div className="space-y-1"><Label>Description</Label><Textarea value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })} rows={2} /></div>
233	            <div className="flex justify-end gap-2">
234	              <Button variant="outline" size="sm" onClick={() => setShowAdd(false)}>Cancel</Button>
235	              <Button size="sm" onClick={handleCreate} disabled={!formData.title}>Create</Button>
236	            </div>
237	          </CardContent>
238	        </Card>
239	      )}
240	
241	      {isLoading ? (
242	        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 flex-1">
243	          {[1, 2, 3].map((i) => <Skeleton key={i} className="h-full w-full rounded-xl" />)}
244	        </div>
245	      ) : (
246	        <>
247	          {view === "kanban" && (
248	            <div className="grid grid-cols-1 md:grid-cols-5 gap-4 flex-1 items-start overflow-x-auto pb-2">
249	              {COLUMNS.map((col) => (
250	                <div key={col.id} className="bg-sidebar rounded-xl p-3 flex flex-col gap-3 max-h-full border border-border min-w-[260px]">
251	                  <div className="flex items-center justify-between">
252	                    <h3 className="font-semibold text-sm flex items-center gap-2">
253	                      {STATUS_LABELS[col.id]}
254	                      <span className="bg-background text-muted-foreground text-xs px-2 py-0.5 rounded-full border border-border">{groupedTasks[col.id].length}</span>
255	                    </h3>
256	                    <Button variant="ghost" size="icon" className="h-6 w-6 rounded-full hover:bg-background" onClick={() => setShowAdd(true)}>
257	                      <Plus className="h-4 w-4" />
258	                    </Button>
259	                  </div>
260	                  <div className="flex flex-col gap-2 overflow-y-auto pr-1">
261	                    {groupedTasks[col.id].map((task) => (
262	                      <TaskCard
263	                        key={task.id}
264	                        task={task}
265	                        users={users ?? []}
266	                        isSelected={selectedTasks.has(task.id)}
267	                        onClick={() => setDetailTask(task)}
268	                        onSelectToggle={() => toggleSelect(task.id)}
269	                      />
270	                    ))}
271	                    {groupedTasks[col.id].length === 0 && (
272	                      <div className="border border-dashed border-border rounded-lg p-4 flex flex-col items-center justify-center text-center opacity-50">
273	                        <CheckSquare className="h-6 w-6 text-muted-foreground mb-1" />
274	                        <p className="text-xs text-muted-foreground">No tasks</p>
275	                      </div>
276	                    )}
277	                  </div>
278	                </div>
279	              ))}
280	            </div>
281	          )}
282	
283	          {view === "table" && (
284	            <div className="border rounded-lg overflow-hidden">
285	              <table className="w-full text-sm">
286	                <thead className="bg-muted/50 border-b">
287	                  <tr>
288	                    <th className="p-2 w-8">
289	                      <button onClick={selectAll} className="flex items-center justify-center w-4 h-4">
290	                        <div className={`w-4 h-4 rounded border flex items-center justify-center ${
291	                          tasks && tasks.length > 0 && selectedTasks.size === tasks.length
292	                            ? "bg-primary border-primary text-primary-foreground" : "border-muted-foreground"
293	                        }`}>
294	                          {tasks && tasks.length > 0 && selectedTasks.size === tasks.length && (
295	                            <Check className="h-3 w-3" />
296	                          )}
297	                        </div>
298	                      </button>
299	                    </th>
300	                    <th className="p-2 text-left font-medium text-xs uppercase tracking-wider text-muted-foreground">Task</th>
301	                    <th className="p-2 text-left font-medium text-xs uppercase tracking-wider text-muted-foreground">Status</th>
302	                    <th className="p-2 text-left font-medium text-xs uppercase tracking-wider text-muted-foreground">Priority</th>
303	                    <th className="p-2 text-left font-medium text-xs uppercase tracking-wider text-muted-foreground">Assignees</th>
304	                    <th className="p-2 text-left font-medium text-xs uppercase tracking-wider text-muted-foreground">Due</th>
305	                    <th className="p-2 text-left font-medium text-xs uppercase tracking-wider text-muted-foreground">Tags</th>
306	                    <th className="p-2 w-10" />
307	                  </tr>
308	                </thead>
309	                <tbody className="divide-y">
310	                  {tasks?.map((task) => (
311	                    <tr
312	                      key={task.id}
313	                      className={`hover:bg-muted/30 transition-colors cursor-pointer ${selectedTasks.has(task.id) ? "bg-primary/5" : ""}`}
314	                      onClick={() => setDetailTask(task)}
315	                    >
316	                      <td className="p-2" onClick={(e) => { e.stopPropagation(); toggleSelect(task.id); }}>
317	                        <div className={`w-4 h-4 rounded border flex items-center justify-center ${
318	                          selectedTasks.has(task.id) ? "bg-primary border-primary text-primary-foreground" : "border-muted-foreground"
319	                        }`}>
320	                          {selectedTasks.has(task.id) && <Check className="h-3 w-3" />}
321	                        </div>
322	                      </td>
323	                      <td className="p-2">
324	                        <div className="font-medium text-sm">{task.title}</div>
325	                        {task.description && <div className="text-xs text-muted-foreground line-clamp-1">{task.description}</div>}
326	                      </td>
327	                      <td className="p-2">
328	                        <Badge variant="outline" className={`text-[10px] ${STATUS_COLORS[task.status]}`}>
329	                          {STATUS_LABELS[task.status]}
330	                        </Badge>
331	                      </td>
332	                      <td className="p-2">
333	                        <Badge variant="outline" className={`text-[10px] ${PRIORITY_COLORS[task.priority]}`}>
334	                          {task.priority}
335	                        </Badge>
336	                      </td>
337	                      <td className="p-2">
338	                        <div className="flex -space-x-1">
339	                          {task.assigneeIds.slice(0, 3).map((id) => {
340	                            const u = users?.find((x) => x.id === id);
341	                            const initial = (u?.firstName?.[0] ?? u?.email?.[0] ?? "?").toUpperCase();
342	                            return (
343	                              <div key={id} className="h-5 w-5 rounded-full bg-primary/20 text-primary flex items-center justify-center text-[9px] ring-1 ring-background">
344	                                {initial}
345	                              </div>
346	                            );
347	                          })}
348	                          {task.assigneeIds.length > 3 && (
349	                            <div className="h-5 w-5 rounded-full bg-muted text-muted-foreground flex items-center justify-center text-[9px] ring-1 ring-background">
350	                              +{task.assigneeIds.length - 3}
351	                            </div>
352	                          )}
353	                        </div>
354	                      </td>
355	                      <td className="p-2 text-xs text-muted-foreground">
356	                        {task.dueDate ? format(new Date(task.dueDate), "MMM d") : "—"}
357	                      </td>
358	                      <td className="p-2">
359	                        <div className="flex gap-1 flex-wrap">
360	                          {task.tags.map((tag) => (
361	                            <Badge key={tag} variant="outline" className="text-[9px] px-1 h-4">{tag}</Badge>
362	                          ))}
363	                        </div>
364	                      </td>
365	                      <td className="p-2">
366	                        <DropdownMenu>
367	                          <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
368	                            <Button variant="ghost" size="icon" className="h-7 w-7"><MoreHorizontal className="h-4 w-4" /></Button>
369	                          </DropdownMenuTrigger>
370	                          <DropdownMenuContent align="end">
371	                            <DropdownMenuItem onClick={() => setDetailTask(task)}><Edit2 className="h-4 w-4 mr-2" /> Edit</DropdownMenuItem>
372	                            <DropdownMenuItem onClick={() => { deleteTask.mutate({ projectId, taskId: task.id }); qc.invalidateQueries({ queryKey: getListRichTasksQueryKey(projectId) }); }} className="text-destructive focus:text-destructive"><Trash2 className="h-4 w-4 mr-2" /> Delete</DropdownMenuItem>
373	                          </DropdownMenuContent>
374	                        </DropdownMenu>
375	                      </td>
376	                    </tr>
377	                  ))}
378	                </tbody>
379	              </table>
380	            </div>
381	          )}
382	
383	          {view === "calendar" && (
384	            <div className="flex flex-col h-full">
385	              <div className="grid grid-cols-7 gap-1 text-center text-xs text-muted-foreground mb-2">
386	                {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((d) => (
387	                  <div key={d} className="py-1 font-medium">{d}</div>
388	                ))}
389	              </div>
390	              <div className="grid grid-cols-7 gap-1 flex-1">
391	                {calendarDays.map((day) => {
392	                  const dayTasks = tasks?.filter((t) => t.dueDate && isSameDay(new Date(t.dueDate), day)) ?? [];
393	                  return (
394	                    <div
395	                      key={day.toISOString()}
396	                      className={`border rounded-md p-1.5 min-h-[100px] ${isToday(day) ? "bg-primary/5 border-primary/30" : "bg-card border-border"}`}
397	                    >
398	                      <div className={`text-xs font-medium mb-1 ${isToday(day) ? "text-primary" : "text-muted-foreground"}`}>
399	                        {format(day, "d")}
400	                      </div>
401	                      <div className="space-y-1">
402	                        {dayTasks.map((task) => (
403	                          <button
404	                            key={task.id}
405	                            onClick={() => setDetailTask(task)}
406	                            className={`text-[10px] w-full text-left px-1.5 py-0.5 rounded truncate block ${PRIORITY_COLORS[task.priority]} border`}
407	                          >
408	                            {task.title}
409	                          </button>
410	                        ))}
411	                      </div>
412	                    </div>
413	                  );
414	                })}
415	              </div>
416	            </div>
417	          )}
418	        </>
419	      )}
420	
421	      <TaskDetailDrawer
422	        task={detailTask}
423	        open={!!detailTask}
424	        onOpenChange={(open) => !open && setDetailTask(null)}
425	        projectId={projectId}
426	      />
427	    </div>
428	  );
429	}
