                            const initial = (u?.firstName?.[0] ?? u?.email?.[0] ?? "?").toUpperCase();
                            return (
                              <div key={id} className="h-5 w-5 rounded-full bg-primary/20 text-primary flex items-center justify-center text-[9px] ring-1 ring-background">
