120	function relativeTime(dateStr: string): string {
121	  const diff = Date.now() - new Date(dateStr).getTime();
122	  const mins = Math.floor(diff / 60000);
123	  if (mins < 1) return "just now";
124	  if (mins < 60) return `${mins}m ago`;
125	  const hrs = Math.floor(mins / 60);
126	  if (hrs < 24) return `${hrs}h ago`;
127	  const days = Math.floor(hrs / 24);
128	  if (days < 7) return `${days}d ago`;
129	  return new Date(dateStr).toLocaleDateString();
130	}
