            </div>
          </div>

          {/* Collaboration */}
          <CollaborationDashboard projectId={projectId} />
        </>
      )}

      {/* ── Game Bible — only on identity tab, expanded inline ─────────────── */}
      {view === "identity" && (
        <Card className="overflow-hidden">
          <CardHeader className="py-4 px-5 border-b border-border bg-card">
