type SaveStatus = "idle" | "saving" | "saved";
type SectionKey = "hero" | "fingerprint" | "problems" | "decisions" | "playtest" | "bible" | "phase";

/* ─── Game Status Widget ────────────────────────────────────────────────────── */

interface GameStatusWidgetProps {
  entityTotal: number;
  entityPct: number;
  ruleTotal: number;
  experimentalRules: number;
  playerTotal: number;
  playtestTotal: number;
  playtestScheduled: number;
  blockerCount: number;
  concernCount: number;
  balanceScore: number | null;
  balanceScoreLabel: string;
  balanceScoreColor: string;
  balanceVerdict: string;
  nextStep: { label: string; action: "playtest" | "none" };
  onSchedulePlaytest: () => void;
}

function MetricRow({
  icon: Icon,
  label,
  value,
  detail,
  detailColor,
  valueColor = "text-foreground",
}: {
  icon: React.ElementType;
  label: string;
  value: string | number;
  detail?: React.ReactNode;
  detailColor?: string;
  valueColor?: string;
}) {
  return (
    <div className="flex items-center gap-3 py-2 border-b border-border/40 last:border-0">
      <Icon className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
      <span className="text-xs text-muted-foreground w-36 shrink-0">{label}</span>
      <span className={`text-xs font-semibold tabular-nums ${valueColor}`}>{value}</span>
      {detail && (
        <span className={`text-[10px] ml-auto ${detailColor ?? "text-muted-foreground"}`}>
          {detail}
        </span>
      )}
    </div>
  );
}

function BalanceBar({ score }: { score: number }) {
  const color = score >= 80 ? "bg-emerald-500" : score >= 65 ? "bg-lime-500" : score >= 45 ? "bg-amber-500" : "bg-red-500";
  return (
    <div className="flex items-center gap-2 flex-1">
      <div className="flex-1 h-1.5 bg-muted rounded-full overflow-hidden">
        <div className={`h-full ${color} rounded-full transition-all duration-700`} style={{ width: `${score}%` }} />
      </div>
      <span className="text-[10px] text-muted-foreground tabular-nums">{score}/100</span>
    </div>
  );
}

function GameStatusWidget({
  entityTotal, entityPct, ruleTotal, experimentalRules,
  playerTotal, playtestTotal, playtestScheduled,
  blockerCount, concernCount, balanceScore, balanceScoreLabel, balanceScoreColor,
  nextStep, onSchedulePlaytest,
}: GameStatusWidgetProps) {
  const overallHealth = (() => {
    if (blockerCount > 0) return { label: "Blocked", color: "text-red-400", bg: "bg-red-500/10 border-red-500/30" };
    if (concernCount > 2 || (balanceScore !== null && balanceScore < 45)) return { label: "At risk", color: "text-amber-400", bg: "bg-amber-500/10 border-amber-500/30" };
    if (entityTotal === 0 || ruleTotal === 0 || playerTotal === 0) return { label: "Early stage", color: "text-sky-400", bg: "bg-sky-500/10 border-sky-500/30" };
    return { label: "On track", color: "text-emerald-400", bg: "bg-emerald-500/10 border-emerald-500/30" };
  })();

  return (
    <Card className="border-border/60">
      <CardHeader className="py-3 px-5 border-b border-border/60">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm font-semibold flex items-center gap-2">
            <Gauge className="h-4 w-4 text-primary" />
            Game Status
          </CardTitle>
          <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-full border ${overallHealth.bg} ${overallHealth.color}`}>
            {overallHealth.label}
          </span>
        </div>
      </CardHeader>
      <CardContent className="px-5 py-3">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-8">
          {/* Left column */}
          <div>
            <MetricRow
              icon={LayoutDashboard}
              label="Components"
              value={entityTotal === 0 ? "None yet" : `${entityTotal} defined`}
              valueColor={entityTotal === 0 ? "text-muted-foreground" : "text-foreground"}
              detail={
                entityTotal > 0 ? (
                  <span className="flex items-center gap-1">
                    <span className={`inline-block w-1.5 h-1.5 rounded-full ${entityPct >= 75 ? "bg-emerald-400" : entityPct >= 40 ? "bg-amber-400" : "bg-red-400"}`} />
                    {entityPct}% detailed
                  </span>
                ) : null
              }
              detailColor={entityPct >= 75 ? "text-emerald-400" : entityPct >= 40 ? "text-amber-400" : "text-red-400"}
            />
            <MetricRow
              icon={Activity}
              label="Rules"
              value={ruleTotal === 0 ? "None yet" : `${ruleTotal} total`}
              valueColor={ruleTotal === 0 ? "text-muted-foreground" : "text-foreground"}
              detail={
                experimentalRules > 0 ? (
                  <span className="flex items-center gap-1 text-amber-400">
                    <FlaskConical className="h-2.5 w-2.5" />
                    {experimentalRules} experimental
                  </span>
                ) : ruleTotal > 0 ? "All stable" : null
              }
              detailColor={experimentalRules > 0 ? "text-amber-400" : "text-emerald-400"}
            />
            <MetricRow
              icon={Users}
              label="Players"
              value={playerTotal === 0 ? "None yet" : `${playerTotal} defined`}
              valueColor={playerTotal === 0 ? "text-muted-foreground" : "text-foreground"}
            />
          </div>

          {/* Right column */}
          <div>
            <MetricRow
              icon={Target}
              label="Playtests"
              value={`${playtestTotal} completed`}
              detail={
                playtestScheduled > 0
                  ? <span className="text-emerald-400">{playtestScheduled} scheduled</span>
                  : <span className="text-amber-400">None scheduled</span>
              }
              detailColor={playtestScheduled > 0 ? "text-emerald-400" : "text-amber-400"}
            />
            <div className="flex items-center gap-3 py-2 border-b border-border/40">
              <ShieldAlert className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
              <span className="text-xs text-muted-foreground w-36 shrink-0">Design Blockers</span>
              {blockerCount === 0 && concernCount === 0 ? (
                <span className="text-xs font-semibold text-emerald-400">None open</span>
              ) : (
                <div className="flex items-center gap-2">
                  {blockerCount > 0 && (
                    <span className="text-xs font-semibold text-red-400 flex items-center gap-0.5">
                      <AlertTriangle className="h-3 w-3" /> {blockerCount} critical
                    </span>
                  )}
                  {concernCount > 0 && (
                    <span className="text-xs font-semibold text-amber-400 flex items-center gap-0.5">
                      <AlertCircle className="h-3 w-3" /> {concernCount} concern{concernCount > 1 ? "s" : ""}
                    </span>
                  )}
                </div>
              )}
            </div>
            <div className="flex items-center gap-3 py-2">
              <TrendingUp className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
              <span className="text-xs text-muted-foreground w-36 shrink-0">Balance Score</span>
              {balanceScore === null ? (
                <span className="text-xs text-muted-foreground italic">Not computed</span>
              ) : (
                <div className="flex items-center gap-2 flex-1">
                  <BalanceBar score={balanceScore} />
                  <span className={`text-[10px] font-semibold shrink-0 ${balanceScoreColor}`}>{balanceScoreLabel}</span>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Divider */}
        <div className="border-t border-border/40 mt-1 pt-3">
          <div className="flex items-center justify-between gap-4">
            <div className="flex items-center gap-2 min-w-0">
              <ArrowRight className="h-3.5 w-3.5 text-primary shrink-0" />
              <span className="text-xs text-muted-foreground truncate">
                <span className="font-semibold text-foreground">NEXT: </span>
                {nextStep.label}
              </span>
            </div>
            {nextStep.action === "playtest" && (
              <Button size="sm" className="h-7 text-xs shrink-0 gap-1.5" onClick={onSchedulePlaytest}>
                <Calendar className="h-3.5 w-3.5" /> Schedule Playtest
              </Button>
            )}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

