168	          onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); add(); } }}
169	          placeholder="Component name…"
170	          className="flex-1 h-7 rounded-md border border-input bg-input px-2 text-[10px] text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-ring"
171	        />
172	        <datalist id={listId}>
173	          {allEntities.map((e) => <option key={e.id} value={e.name} />)}
174	        </datalist>
175	        <Button type="button" size="sm" variant="outline" className="h-7 px-2 shrink-0" onClick={add} disabled={!addName.trim()}>
176	          <Plus className="w-3 h-3" />
177	        </Button>
178	      </div>
179	    </div>
180	  );
181	}
182	
183	// ─────────────────────────────────────────────────────────────────────────────
184	
185	interface EntitiesProps {
186	  projectId: number;
187	}
188	
189	// ─── Main component ────────────────────────────────────────────────────────────
190	
191	export function Entities({ projectId }: EntitiesProps) {
192	  const queryClient = useQueryClient();
193	  const { data: entities, isLoading } = useListEntities(projectId);
194	  const { data: project } = useGetProject(projectId);
