  allEntities: Entity[];
  listId: string;
}) {
  const rels = parseRelationships(value);
  const [addVerb, setAddVerb] = useState("");
  const [addName, setAddName] = useState("");

  const remove = (idx: number) =>
    onChange(serializeRelationships(rels.filter((_, i) => i !== idx)));

  const add = () => {
    const trimmed = addName.trim();
