    onChange(serializeRelationships([...rels, { verb: addVerb || undefined, name: trimmed }]));
    setAddName("");
  };

  return (
    <div className="space-y-1.5">
      {rels.length > 0 && (
        <div className="flex flex-wrap gap-1">
          {rels.map((r, i) => (
