              {r.verb && <span className="opacity-60 font-medium">{r.verb}:</span>}
              {r.name}
              <button type="button" onClick={() => remove(i)} className="text-cyan-400/50 hover:text-destructive ml-0.5">
                <X className="w-2.5 h-2.5" />
              </button>
            </span>
          ))}
        </div>
      )}
      <div className="flex gap-1.5 items-center">
