        </Select>
        <input
          list={listId}
          value={addName}
          onChange={(e) => setAddName(e.target.value)}
          onKeyDown={(e) => { if (e.key === "Enter") { e.preventDefault(); add(); } }}
          placeholder="Component name…"
          className="flex-1 h-7 rounded-md border border-input bg-input px-2 text-[10px] text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-ring"
        />
        <datalist id={listId}>
          {allEntities.map((e) => <option key={e.id} value={e.name} />)}
