import type { ComponentType } from "@/lib/game-component-types";

export interface StatRange {
  name: string;
  min: number;
  max: number;
  step?: number;
  description?: string;
}

export interface EntityTemplate {
  id: string;
  name: string;
  entityType: ComponentType;
  subtype?: string;
  icon: string;
  description: string;
  accentColor: string;
  bgColor: string;
  statRanges: StatRange[];
  descriptionHint: string;
  namingHint: string;
}

