// ─── Quick-Create Template Panel ────────────────────────────────────────────

interface TemplatePanelProps {
  onClose: () => void;
  onCreate: (entities: { name: string; type: ComponentType; subtype: string; stats: string; description: string }[]) => Promise<void>;
  isCreating: boolean;
}

function TemplatePanel({ onClose, onCreate, isCreating }: TemplatePanelProps) {
  const [selected, setSelected]   = useState<EntityTemplate | null>(null);
  const [namePrefix, setNamePrefix] = useState("");
  const [count, setCount]         = useState(1);
  const [tier, setTier]           = useState(1);
  const [statOverrides, setStatOverrides] = useState<Record<string, number>>({});

  const resetSelection = () => {
    setSelected(null);
    setNamePrefix("");
    setCount(1);
    setTier(1);
    setStatOverrides({});
  };

  const handleTemplateClick = (tmpl: EntityTemplate) => {
    setSelected(tmpl);
    setNamePrefix("");
    setCount(1);
    setTier(1);
    setStatOverrides({});
  };

  const previewStats = selected
    ? selected.statRanges.map((r) => ({
        ...r,
        preview: r.name in statOverrides ? statOverrides[r.name] : previewStatValue(r, tier),
      }))
    : [];

  const handleGenerate = async () => {
    if (!selected || !namePrefix.trim()) return;
    const base = namePrefix.trim();
    const batch = Array.from({ length: count }, (_, i) => {
      const entityName = count === 1 ? base : `${base} ${i + 1}`;
      return {
        name: entityName,
        type: selected.entityType,
        subtype: selected.subtype ?? "",
        stats: buildStatsForTier(selected, tier, statOverrides),
        description: "",
      };
    });
    await onCreate(batch);
  };

  const tierInfo = TIER_LABELS[tier];

  if (!selected) {
    // Template grid — pick a template
    return (
      <Card className="p-4 bg-card border-border space-y-3">
        <div className="flex items-center justify-between">
          <p className="text-xs font-semibold text-foreground flex items-center gap-1.5">
            <LayoutTemplate className="w-3.5 h-3.5 text-primary" /> Select Template
          </p>
          <button onClick={onClose} className="text-muted-foreground hover:text-white">
            <X className="w-3.5 h-3.5" />
          </button>
        </div>
        <p className="text-[11px] text-muted-foreground">
          Choose a template to fast-create entities with pre-filled stats and properties.
        </p>
        <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-6 gap-2">
          {ENTITY_TEMPLATES.map((tmpl) => (
            <button
              key={tmpl.id}
              onClick={() => handleTemplateClick(tmpl)}
              className={`flex flex-col items-start gap-2 p-3 rounded-lg border text-left transition-all hover:border-primary/50 hover:bg-primary/5 ${tmpl.bgColor}`}
            >
              <div className="flex items-center gap-2">
                <span className="text-lg">{tmpl.icon}</span>
                <span className={`text-xs font-semibold ${tmpl.accentColor}`}>{tmpl.name}</span>
              </div>
              <div className="space-y-0.5 w-full">
                {tmpl.statRanges.slice(0, 4).map((r) => (
                  <div key={r.name} className="flex items-center justify-between text-[10px]">
                    <span className="text-muted-foreground">+{r.name}</span>
                    <span className="text-muted-foreground/60">{r.min}–{r.max}</span>
                  </div>
                ))}
              </div>
              <span className="text-[10px] text-muted-foreground/60 leading-tight">{tmpl.description}</span>
            </button>
          ))}
        </div>
      </Card>
    );
  }

  // Configuration form for selected template
  return (
    <Card className={`p-4 bg-card border space-y-4 ${selected.bgColor}`}>
      <div className="flex items-center justify-between">
        <button
          onClick={resetSelection}
          className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors"
        >
          <ChevronLeft className="w-3.5 h-3.5" /> Templates
        </button>
        <div className="flex items-center gap-2">
          <span className="text-sm">{selected.icon}</span>
          <span className={`text-sm font-semibold ${selected.accentColor}`}>{selected.name} Template</span>
        </div>
        <button onClick={onClose} className="text-muted-foreground hover:text-white">
          <X className="w-3.5 h-3.5" />
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
        {/* Name prefix */}
        <div className="space-y-1">
          <Label className="text-xs">Base Name *</Label>
          <Input
            autoFocus
            value={namePrefix}
            onChange={(e) => setNamePrefix(e.target.value)}
            placeholder={selected.namingHint}
            className="h-8 bg-input text-sm"
          />
          <p className="text-[10px] text-muted-foreground">
            {count > 1 ? `Creates: ${namePrefix || "…"} 1, ${namePrefix || "…"} 2…` : "Single entity name"}
          </p>
        </div>

        {/* Count */}
        <div className="space-y-1">
          <Label className="text-xs flex items-center gap-1.5">
            <Dices className="w-3.5 h-3.5" /> Generate Count
          </Label>
          <div className="flex gap-1">
            {[1, 2, 3, 5, 8, 10].map((n) => (
              <button
                key={n}
                onClick={() => setCount(n)}
                className={`flex-1 h-8 rounded-md border text-xs font-semibold transition-all ${
                  count === n
                    ? `${selected.bgColor} ${selected.accentColor} ring-1 ring-current`
                    : "border-border text-muted-foreground hover:text-foreground"
                }`}
              >
                {n}
              </button>
            ))}
          </div>
        </div>

        {/* Tier */}
        <div className="space-y-1">
          <Label className="text-xs flex items-center justify-between">
            <span>Tier</span>
            <span className={`text-[10px] font-semibold ${tierInfo.color}`}>{tierInfo.label}</span>
          </Label>
          <div className="flex gap-1">
            {[1, 2, 3, 4, 5].map((t) => (
              <button
                key={t}
                onClick={() => { setTier(t); setStatOverrides({}); }}
                className={`flex-1 h-8 rounded-md border text-xs font-bold transition-all ${
                  tier === t
                    ? `${selected.bgColor} ${TIER_LABELS[t].color} ring-1 ring-current`
                    : "border-border text-muted-foreground hover:text-foreground"
                }`}
              >
                {t}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Stat preview + overrides */}
      <div className="space-y-1.5">
        <Label className="text-xs text-muted-foreground">Stat Preview <span className="font-normal">(click to override)</span></Label>
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
          {previewStats.map((stat) => (
            <div key={stat.name} className="space-y-0.5">
              <div className="flex items-center justify-between">
                <span className="text-[10px] text-muted-foreground">{stat.name}</span>
                <span className="text-[10px] text-muted-foreground/50">{stat.min}–{stat.max}</span>
              </div>
              <div className="relative">
                <Input
                  type="number"
                  min={stat.min}
                  max={stat.max}
                  step={stat.step ?? 1}
                  value={stat.preview}
                  onChange={(e) => {
                    const v = Math.max(stat.min, Math.min(stat.max, parseInt(e.target.value) || stat.min));
                    setStatOverrides((prev) => ({ ...prev, [stat.name]: v }));
                  }}
                  className={`h-8 bg-input text-xs text-center font-mono ${stat.name in statOverrides ? `ring-1 ring-current ${selected.accentColor}` : ""}`}
                />
                {/* Mini bar showing position in range */}
                <div className="h-0.5 bg-muted rounded-full mt-0.5 overflow-hidden">
                  <div
                    className={`h-full ${selected.accentColor.replace("text-", "bg-")} rounded-full transition-all`}
                    style={{ width: `${Math.round(((stat.preview - stat.min) / Math.max(1, stat.max - stat.min)) * 100)}%` }}
                  />
                </div>
              </div>
            </div>
          ))}
        </div>
        {Object.keys(statOverrides).length > 0 && (
          <button
            onClick={() => setStatOverrides({})}
            className="text-[10px] text-muted-foreground hover:text-foreground underline"
          >
            Reset overrides
          </button>
        )}
      </div>

      <div className="flex items-center justify-between pt-1">
        <p className="text-[11px] text-muted-foreground">
          {count > 1
            ? `Will create ${count} ${selected.name.toLowerCase()}s with Tier ${tier} stats ± random variance.`
            : `Will create 1 ${selected.name.toLowerCase()} with Tier ${tier} stats.`}
        </p>
        <Button
          onClick={handleGenerate}
          disabled={!namePrefix.trim() || isCreating}
          size="sm"
          className="gap-1.5 shrink-0"
        >
          {isCreating
            ? <Loader2 className="w-3.5 h-3.5 animate-spin" />
            : <Sparkles className="w-3.5 h-3.5" />}
          {isCreating ? "Creating…" : `Generate ${count > 1 ? `${count} ` : ""}${selected.name}${count > 1 ? "s" : ""}`}
        </Button>
      </div>
    </Card>
  );
}

