504	}) {
505	  const { toast } = useToast();
506	  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
507	  const [cloneGameId, setCloneGameId] = useState<string>("");
508	  const [direction, setDirection] = useState("");
