510	  // R2: clone destination toggle (new project vs. into current project)
511	  const [cloneDestination, setCloneDestination] = useState<"new_project" | "populate_current">("new_project");
512	  const [synthType, setSynthType] = useState<"synthesize" | "clone">(initialSynthType ?? "synthesize");
513	  const [reversing, setReversing] = useState(false);
514	  const [stageIdx, setStageIdx] = useState(0);
515	
516	  useEffect(() => {
517	    if (open) {
518	      const resolvedSynthType = initialSynthType ?? "synthesize";
519	      setSynthType(resolvedSynthType);
520	      if (resolvedSynthType === "clone") {
521	        // Clone mode: pre-select the single game
522	        const firstId = preselectedGameId && researched.some((g) => g.id === preselectedGameId)
523	          ? preselectedGameId
524	          : (researched[0]?.id ?? "");
525	        setCloneGameId(firstId);
526	        setSelectedIds(new Set(firstId ? [firstId] : []));
527	      } else {
528	        if (preselectedGameId && researched.some((g) => g.id === preselectedGameId)) {
529	          setSelectedIds(new Set([preselectedGameId]));
530	        } else {
531	          setSelectedIds(new Set(researched.map((g) => g.id)));
