539	
540	  // When switching synthType, reset selection
541	  const handleSynthTypeChange = (next: "synthesize" | "clone") => {
542	    setSynthType(next);
543	    if (next === "clone") {
544	      const firstId = cloneGameId || researched[0]?.id || "";
545	      setCloneGameId(firstId);
546	      setSelectedIds(new Set(firstId ? [firstId] : []));
547	    } else {
548	      setSelectedIds(new Set(researched.map((g) => g.id)));
