import { useEffect, useState } from "react";
import { useLocation } from "wouter";
import { useQueryClient } from "@tanstack/react-query";
import {
  useGetProject, useUpdateProject, useListResearch, getListResearchQueryKey,
  useCreateResearch, useUpdateResearch, useDeleteResearch, useAiEnhanceResearch,
  useListReferenceGames, getListReferenceGamesQueryKey,
  useCreateReferenceGame, useDeleteReferenceGame, useUpdateReferenceGame,
} from "@workspace/api-client-react";
import { useToast } from "@/hooks/use-toast";
import { useDebounce } from "@/hooks/use-debounce";
import {
  Heart, Sparkles, Plus, X, Wand2, Loader2, GripVertical, Trash2, Search,
  ExternalLink, Edit2, Tag, Lightbulb, Compass, StickyNote, TrendingUp,
  MessageCircle, Zap, ChevronRight, CheckCircle2, ChevronDown, ChevronUp,
  Users, Clock, BarChart2, FileText, RefreshCw, ArrowRight,
  AlertTriangle, Check, Copy, Eye, RotateCcw,
} from "lucide-react";
import { Reorder, useDragControls } from "framer-motion";
import { apiBase, workspacesApi } from "@/lib/workspaces-api";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel,
  AlertDialogContent, AlertDialogDescription,
  AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Checkbox } from "@/components/ui/checkbox";
import { GAME_TEMPLATES, type GameTemplate } from "@/lib/game-templates";

/* ── types ───────────────────────────────────────────────────────────── */

type GameData = {
  overview?: string;
  coreLoop?: string;
  keyMechanics?: string[];
  playerCount?: string;
  playTime?: string;
  complexity?: string;
  designStrengths?: string[];
  designWeaknesses?: string[];
  designLessons?: string;
  tags?: string;
};

type RefGame = {
  id: string;
  name: string;
  borrowing: string;
  avoiding: string;
  researchId?: number;
  gameData?: GameData;
};

interface CompGame {
  id: string;
  game: string;
  players: string;
  duration: string;
  complexity: number; // 1–5
  funFactor: number;  // 1–10
  loveAbout: string;
  wouldDoBetter: string;
  notes: string;
}

/* ── helpers ─────────────────────────────────────────────────────────── */


const COMP_KEY = (pid: number) => `gameforge.comp.${pid}`;
function loadComp(pid: number): CompGame[] {
  try { const r = localStorage.getItem(COMP_KEY(pid)); return r ? JSON.parse(r) : []; } catch { return []; }
}
function saveComp(pid: number, list: CompGame[]) {
  try { localStorage.setItem(COMP_KEY(pid), JSON.stringify(list)); } catch {}
}

const QUICK_QUESTIONS = [
  "What are the biggest design risks in this game?",
  "How can I make player interaction more exciting?",
  "What rules might conflict with each other?",
  "Suggest a unique mechanic based on my setup",
  "How does the complexity compare to similar games?",
  "What's the most satisfying moment in my game right now?",
];

const QUICK_PROMPTS = [
  "Brainstorm core mechanics for this genre.",
  "Suggest 5 unique player roles.",
  "Draft a quick summary of the rulebook.",
  "What are some interesting twists for the endgame?",
];

const COMPLEXITY_LABELS: Record<number, string> = { 1: "Pick up & play", 2: "Easy", 3: "Medium", 4: "Complex", 5: "Heavy" };

const REVERSE_STAGES = [
  { label: "Analyzing games…", sub: "KIMI is studying your inspirations" },
  { label: "Synthesizing design DNA…", sub: "Finding patterns across your references" },
  { label: "Designing your game…", sub: "Building mechanics, rules, and roles" },
  { label: "Finalizing blueprint…", sub: "Polishing the final design" },
];

const CLONE_STAGES = [
  { label: "Reading the rulebook…", sub: "KIMI is loading all official rules" },
  { label: "Cataloguing components…", sub: "Mapping real component names and types" },
  { label: "Reconstructing the game…", sub: "Building a faithful replica of the original" },
  { label: "Verifying accuracy…", sub: "Checking player counts, times, and rules" },
];

/* ── sub-components ──────────────────────────────────────────────────── */

function DraggableGameCard({
  game,
  onRemove,
  onResearch,
  onReResearch,
  onReverseEngineer,
  onClone,
  researching,
  canReverseEngineer,
}: {
  game: RefGame;
  onRemove: () => void;
  onResearch: (depth: string) => void;
  onReResearch: () => void;
  onReverseEngineer: (gameId: string) => void;
  onClone: (gameId: string) => void;
  researching: boolean;
  canReverseEngineer: boolean;
}) {
  const controls = useDragControls();
  const [expanded, setExpanded] = useState(false);
  const [confirmRemove, setConfirmRemove] = useState(false);
  const [researchDepth, setResearchDepth] = useState("comprehensive");
  const [showPreview, setShowPreview] = useState(false);
  const hasData = Boolean(game.gameData);

  return (
    <Reorder.Item
      value={game}
      dragListener={false}
      dragControls={controls}
      className="rounded-xl border border-border bg-card overflow-hidden group list-none"
      whileDrag={{ scale: 1.02, boxShadow: "0 8px 24px rgba(0,0,0,0.3)", zIndex: 50 }}
      layout
    >
      {/* Header */}
      <div className="p-4">
        <div className="flex items-start gap-2 mb-3">
          {/* Drag handle */}
          <button
            onPointerDown={(e) => controls.start(e)}
            className="shrink-0 mt-0.5 cursor-grab active:cursor-grabbing text-muted-foreground/40 hover:text-muted-foreground transition-colors touch-none"
            title="Drag to reorder"
          >
            <GripVertical className="h-4 w-4" />
          </button>

          <div className="flex-1 flex items-center gap-2 min-w-0">
            <p className="font-bold text-base leading-tight truncate">{game.name}</p>
            {hasData && (
              <span className="shrink-0 inline-flex items-center gap-1 text-[10px] font-semibold uppercase tracking-wider bg-emerald-500/15 text-emerald-400 border border-emerald-500/25 px-1.5 py-0.5 rounded">
                <CheckCircle2 className="h-2.5 w-2.5" /> Researched
              </span>
            )}
          </div>

          {/* Remove button with inline confirm */}
          {confirmRemove ? (
            <div className="flex items-center gap-1 shrink-0">
              <span className="text-[11px] text-destructive font-medium">Remove?</span>
              <button
                onClick={onRemove}
                className="h-6 w-6 flex items-center justify-center rounded bg-destructive/10 hover:bg-destructive/20 text-destructive transition-colors"
                title="Confirm remove"
              >
                <Check className="h-3 w-3" />
              </button>
              <button
                onClick={() => setConfirmRemove(false)}
                className="h-6 w-6 flex items-center justify-center rounded hover:bg-muted text-muted-foreground transition-colors"
                title="Cancel"
              >
                <X className="h-3 w-3" />
              </button>
            </div>
          ) : (
            <button
              onClick={() => setConfirmRemove(true)}
              className="shrink-0 opacity-0 group-hover:opacity-100 text-muted-foreground/50 hover:text-muted-foreground transition-opacity p-0.5"
              title="Remove this game"
            >
              <X className="h-3.5 w-3.5" />
            </button>
          )}
        </div>

        {/* Stats pills */}
        {hasData && game.gameData && (
          <div className="flex flex-wrap gap-2 mb-3 ml-6">
            {game.gameData.playerCount && (
              <span className="inline-flex items-center gap-1 text-[11px] bg-muted text-muted-foreground px-2 py-0.5 rounded-full">
                <Users className="h-2.5 w-2.5" /> {game.gameData.playerCount}
              </span>
            )}
            {game.gameData.playTime && (
              <span className="inline-flex items-center gap-1 text-[11px] bg-muted text-muted-foreground px-2 py-0.5 rounded-full">
                <Clock className="h-2.5 w-2.5" /> {game.gameData.playTime}
              </span>
            )}
            {game.gameData.complexity && (
              <span className="inline-flex items-center gap-1 text-[11px] bg-muted text-muted-foreground px-2 py-0.5 rounded-full">
                <BarChart2 className="h-2.5 w-2.5" /> {game.gameData.complexity}
              </span>
            )}
          </div>
        )}

        {/* Overview snippet */}
        {hasData && game.gameData?.overview && (
          <p className="text-xs text-muted-foreground leading-relaxed mb-3 ml-6 line-clamp-2">
            {game.gameData.overview}
          </p>
        )}

        {/* Borrowing / avoiding */}
        <div className="space-y-1.5 ml-6">
          {game.borrowing && (
            <p className="text-xs">
              <span className="text-emerald-400 font-semibold">Borrowing: </span>
              <span className="text-muted-foreground">{game.borrowing}</span>
            </p>
          )}
          {game.avoiding && (
            <p className="text-xs">
              <span className="text-amber-400 font-semibold">Doing differently: </span>
              <span className="text-muted-foreground">{game.avoiding}</span>
            </p>
          )}
        </div>
      </div>

      {/* Footer actions */}
      <div className="border-t border-border px-4 py-2.5 flex items-center gap-2 flex-wrap">
        {!hasData ? (
          <div className="flex items-center gap-2">
            <select
              value={researchDepth}
              onChange={(e) => setResearchDepth(e.target.value)}
              className="text-[10px] bg-muted border border-border rounded px-2 py-1 text-foreground"
              title="Research depth"
            >
              <option value="basic">Basic</option>
              <option value="comprehensive">Comprehensive</option>
              <option value="exhaustive">Exhaustive</option>
            </select>
            <Button
              size="sm" variant="outline"
              className="gap-1.5 text-xs h-7 border-primary/30 hover:bg-primary/10"
              onClick={() => onResearch(researchDepth)}
              disabled={researching}
            >
              {researching
                ? <><Loader2 className="h-3 w-3 animate-spin" /> Looking it up…</>
                : <><Sparkles className="h-3 w-3 text-primary" /> Research</>}
            </Button>
          </div>
        ) : (
          <>
            <button
              onClick={() => setExpanded((e) => !e)}
              className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors"
            >
              {expanded ? <ChevronUp className="h-3.5 w-3.5" /> : <ChevronDown className="h-3.5 w-3.5" />}
              {expanded ? "Hide breakdown" : "Full breakdown"}
            </button>

            <button
              onClick={onReResearch}
              disabled={researching}
              className="flex items-center gap-1 text-xs text-muted-foreground hover:text-primary transition-colors disabled:opacity-50"
              title="Refresh AI analysis"
            >
              {researching
                ? <Loader2 className="h-3 w-3 animate-spin" />
                : <RefreshCw className="h-3 w-3" />}
              Re-analyze
            </button>

            {canReverseEngineer && (
              <div className="ml-auto flex items-center gap-1.5">
                {/* R3: Preview parsed data before cloning */}
                <Button
                  size="sm" variant="ghost"
                  className="gap-1 text-xs h-7 text-muted-foreground hover:text-foreground px-2"
                  onClick={() => setShowPreview(true)}
                  title="Preview parsed game data"
                >
                  <Eye className="h-3 w-3" /> Preview
                </Button>
                <Button
                  size="sm" variant="outline"
                  data-testid="card-clone-btn"
                  className="gap-1.5 text-xs h-7 border-violet-500/30 text-violet-400 hover:bg-violet-500/10"
                  onClick={() => onClone(game.id)}
                  title="Faithfully reconstruct this exact game"
                >
                  <Copy className="h-3 w-3" /> Clone
                </Button>
                {/* R1: Re-clone quick button */}
                <Button
                  size="sm" variant="ghost"
                  className="gap-1 text-xs h-7 text-violet-400/70 hover:text-violet-400 px-2"
                  onClick={() => onClone(game.id)}
                  title="Re-clone (redo a new clone from updated data)"
                >
                  <RotateCcw className="h-3 w-3" />
                </Button>
                <Button
                  size="sm" variant="outline"
                  className="gap-1.5 text-xs h-7 border-violet-500/30 text-violet-400 hover:bg-violet-500/10"
                  onClick={() => onReverseEngineer(game.id)}
                  title="Synthesize an original game inspired by this one"
                >
                  <Wand2 className="h-3 w-3" /> Reverse engineer
                </Button>
              </div>
            )}

            {/* R3: Preview modal */}
            {showPreview && game.gameData && (
              <Dialog open={showPreview} onOpenChange={setShowPreview}>
                <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
                  <DialogHeader>
                    <DialogTitle className="flex items-center gap-2">
                      <Eye className="h-5 w-5 text-violet-400" />
                      {game.name} — Game Data Preview
                    </DialogTitle>
                  </DialogHeader>
                  <div className="space-y-4 pt-2">
                    {game.gameData.overview && (
                      <div>
                        <p className="text-[10px] uppercase tracking-wider font-semibold text-muted-foreground mb-1">Overview</p>
                        <p className="text-sm leading-relaxed">{game.gameData.overview}</p>
                      </div>
                    )}
                    {game.gameData.coreLoop && (
                      <div>
                        <p className="text-[10px] uppercase tracking-wider font-semibold text-muted-foreground mb-1">Core loop</p>
                        <p className="text-sm leading-relaxed text-muted-foreground">{game.gameData.coreLoop}</p>
                      </div>
                    )}
                    {game.gameData.keyMechanics?.length ? (
                      <div>
                        <p className="text-[10px] uppercase tracking-wider font-semibold text-muted-foreground mb-2">Key mechanics</p>
                        <div className="flex flex-wrap gap-1.5">
                          {game.gameData.keyMechanics.map((m, mi) => (
                            <span key={mi} className="text-xs bg-primary/10 border border-primary/20 text-primary px-2 py-0.5 rounded-full">{m}</span>
                          ))}
                        </div>
                      </div>
                    ) : null}
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      {game.gameData.designStrengths?.length ? (
                        <div>
                          <p className="text-[10px] uppercase tracking-wider font-semibold text-emerald-400 mb-1.5">Design strengths</p>
                          <ul className="space-y-1">
                            {game.gameData.designStrengths.map((s, si) => (
                              <li key={si} className="text-xs text-muted-foreground flex gap-1.5">
                                <span className="text-emerald-400 shrink-0">✓</span>{s}
                              </li>
                            ))}
                          </ul>
                        </div>
                      ) : null}
                      {game.gameData.designWeaknesses?.length ? (
                        <div>
                          <p className="text-[10px] uppercase tracking-wider font-semibold text-amber-400 mb-1.5">Watch out for</p>
                          <ul className="space-y-1">
                            {game.gameData.designWeaknesses.map((w, wi) => (
                              <li key={wi} className="text-xs text-muted-foreground flex gap-1.5">
                                <span className="text-amber-400 shrink-0">!</span>{w}
                              </li>
                            ))}
                          </ul>
                        </div>
                      ) : null}
                    </div>
                    {game.gameData.designLessons && (
                      <div className="rounded-lg bg-primary/5 border border-primary/20 p-3">
                        <p className="text-[10px] uppercase tracking-wider font-semibold text-primary mb-1">Designer takeaway</p>
                        <p className="text-sm leading-relaxed">{game.gameData.designLessons}</p>
                      </div>
                    )}
                    <div className="flex justify-end gap-2 pt-2 border-t border-border">
                      <Button variant="outline" size="sm" onClick={() => setShowPreview(false)}>Close</Button>
                      <Button size="sm" className="gap-1.5 bg-violet-500 hover:bg-violet-600 text-white" onClick={() => { setShowPreview(false); onClone(game.id); }}>
                        <Copy className="h-3.5 w-3.5" /> Clone this game
                      </Button>
                    </div>
                  </div>
                </DialogContent>
              </Dialog>
            )}
          </>
        )}

        {game.researchId && !hasData && (
          <span className="ml-auto inline-flex items-center gap-1 text-[10px] text-muted-foreground">
            <FileText className="h-3 w-3" /> In notes
          </span>
        )}
      </div>

      {/* Expanded breakdown */}
      {expanded && hasData && game.gameData && (
        <div className="border-t border-border bg-muted/20 px-4 py-4 space-y-4">
          {game.gameData.overview && (
            <div>
              <p className="text-[10px] uppercase tracking-wider font-semibold text-muted-foreground mb-1">Overview</p>
              <p className="text-sm leading-relaxed">{game.gameData.overview}</p>
            </div>
          )}
          {game.gameData.coreLoop && (
            <div>
              <p className="text-[10px] uppercase tracking-wider font-semibold text-muted-foreground mb-1">How it plays</p>
              <p className="text-sm leading-relaxed text-muted-foreground">{game.gameData.coreLoop}</p>
            </div>
          )}
          {game.gameData.keyMechanics?.length ? (
            <div>
              <p className="text-[10px] uppercase tracking-wider font-semibold text-muted-foreground mb-2">Key mechanics</p>
              <div className="flex flex-wrap gap-1.5">
                {game.gameData.keyMechanics.map((m, mi) => (
                  <span key={mi} className="text-xs bg-primary/10 border border-primary/20 text-primary px-2 py-0.5 rounded-full">{m}</span>
                ))}
              </div>
            </div>
          ) : null}
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {game.gameData.designStrengths?.length ? (
              <div>
                <p className="text-[10px] uppercase tracking-wider font-semibold text-emerald-400 mb-1.5">What makes it great</p>
                <ul className="space-y-1">
                  {game.gameData.designStrengths.map((s, si) => (
                    <li key={si} className="text-xs text-muted-foreground flex gap-1.5">
                      <span className="text-emerald-400 shrink-0 mt-0.5">✓</span>{s}
                    </li>
                  ))}
                </ul>
              </div>
            ) : null}
            {game.gameData.designWeaknesses?.length ? (
              <div>
                <p className="text-[10px] uppercase tracking-wider font-semibold text-amber-400 mb-1.5">Watch out for</p>
                <ul className="space-y-1">
                  {game.gameData.designWeaknesses.map((w, wi) => (
                    <li key={wi} className="text-xs text-muted-foreground flex gap-1.5">
                      <span className="text-amber-400 shrink-0 mt-0.5">!</span>{w}
                    </li>
                  ))}
                </ul>
              </div>
            ) : null}
          </div>
          {game.gameData.designLessons && (
            <div className="rounded-lg bg-primary/5 border border-primary/20 p-3">
              <p className="text-[10px] uppercase tracking-wider font-semibold text-primary mb-1">Designer takeaway</p>
              <p className="text-sm leading-relaxed">{game.gameData.designLessons}</p>
            </div>
          )}
        </div>
      )}
    </Reorder.Item>
  );
}

/* ── ReverseEngineerDialog ───────────────────────────────────────────── */

function ReverseEngineerDialog({
  open,
  onClose,
  researched,
  projectId,
  workspaceSlug,
  preselectedGameId,
  initialSynthType,
  onSuccess,
}: {
  open: boolean;
  onClose: () => void;
  researched: RefGame[];
  projectId: number;
  workspaceSlug?: string;
  preselectedGameId: string | null;
  initialSynthType?: "synthesize" | "clone";
  onSuccess: (result: { project: { name: string; slug?: string; id: number }; workspaceSlug?: string; mode: string; synthType?: string }) => void;
}) {
  const { toast } = useToast();
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [cloneGameId, setCloneGameId] = useState<string>("");
  const [direction, setDirection] = useState("");
  const [mode, setMode] = useState<"new_project" | "populate_current">(workspaceSlug ? "new_project" : "populate_current");
  // R2: clone destination toggle (new project vs. into current project)
  const [cloneDestination, setCloneDestination] = useState<"new_project" | "populate_current">("new_project");
  const [synthType, setSynthType] = useState<"synthesize" | "clone">(initialSynthType ?? "synthesize");
  const [reversing, setReversing] = useState(false);
  const [stageIdx, setStageIdx] = useState(0);

  useEffect(() => {
    if (open) {
      const resolvedSynthType = initialSynthType ?? "synthesize";
      setSynthType(resolvedSynthType);
      if (resolvedSynthType === "clone") {
        // Clone mode: pre-select the single game
        const firstId = preselectedGameId && researched.some((g) => g.id === preselectedGameId)
          ? preselectedGameId
          : (researched[0]?.id ?? "");
        setCloneGameId(firstId);
        setSelectedIds(new Set(firstId ? [firstId] : []));
      } else {
        if (preselectedGameId && researched.some((g) => g.id === preselectedGameId)) {
          setSelectedIds(new Set([preselectedGameId]));
        } else {
          setSelectedIds(new Set(researched.map((g) => g.id)));
        }
      }
      setDirection("");
      setMode(workspaceSlug ? "new_project" : "populate_current");
      setStageIdx(0);
    }
  }, [open, researched, preselectedGameId, workspaceSlug, initialSynthType]);

  // When switching synthType, reset selection
  const handleSynthTypeChange = (next: "synthesize" | "clone") => {
    setSynthType(next);
    if (next === "clone") {
      const firstId = cloneGameId || researched[0]?.id || "";
      setCloneGameId(firstId);
      setSelectedIds(new Set(firstId ? [firstId] : []));
    } else {
      setSelectedIds(new Set(researched.map((g) => g.id)));
    }
  };

  const stages = synthType === "clone" ? CLONE_STAGES : REVERSE_STAGES;

  // Cycle through stage labels while reversing
  useEffect(() => {
    if (!reversing) { setStageIdx(0); return; }
    const interval = setInterval(() => setStageIdx((i) => Math.min(i + 1, stages.length - 1)), 3500);
    return () => clearInterval(interval);
  }, [reversing, stages.length]);

  const toggleAll = () => {
    if (selectedIds.size === researched.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(researched.map((g) => g.id)));
    }
  };

  const toggleGame = (id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) { next.delete(id); } else { next.add(id); }
      return next;
    });
  };

  const selectedGames = researched.filter((g) => selectedIds.has(g.id));
  // For clone mode, we send exactly one game (the cloneGameId selection)
  const cloneGame = researched.find((g) => g.id === cloneGameId) ?? null;

  const run = async () => {
    if (synthType === "clone") {
      if (!cloneGame) {
        toast({ title: "Select a game to clone", variant: "destructive" });
        return;
      }
    } else if (selectedGames.length === 0) {
      toast({ title: "Select at least one game", variant: "destructive" });
      return;
    }
    const gamesToSend = synthType === "clone" ? [cloneGame!] : selectedGames;
    // Clone mode always creates a new project
    const effectiveMode = synthType === "clone" ? cloneDestination : mode;
    const effectiveWorkspaceSlug = synthType === "clone" ? (workspaceSlug ?? "") : workspaceSlug;
    if (synthType === "clone" && !workspaceSlug) {
      toast({ title: "Clone requires a workspace context", description: "Open this from a project page to enable cloning.", variant: "destructive" });
      return;
    }
    setReversing(true);
    try {
      const res = await fetch(`${apiBase()}/api/projects/${projectId}/reverse-engineer`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ games: gamesToSend, direction: direction.trim(), mode: effectiveMode, workspaceSlug: effectiveWorkspaceSlug, synthType }),
      });
      if (!res.ok) {
        const err = await res.json().catch(() => ({ error: "Unknown error" }));
        throw new Error(err.error ?? "Clone failed");
      }
      const result = await res.json();
      onSuccess(result);
      onClose();
    } catch (err) {
      toast({ title: "Clone failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
    } finally {
      setReversing(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(o) => !o && !reversing && onClose()}>
      <DialogContent className="max-w-lg flex flex-col max-h-[90vh]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            {synthType === "clone"
              ? <><Copy className="h-5 w-5 text-violet-400" /> Clone Game</>
              : <><Wand2 className="h-5 w-5 text-violet-400" /> Reverse Engineer</>
            }
            <span className="ml-auto text-[10px] font-normal bg-violet-500/10 border border-violet-500/20 text-violet-300 px-2 py-0.5 rounded-full">Powered by AI</span>
          </DialogTitle>
        </DialogHeader>

        {reversing ? (
          /* Progress state */
          <div className="py-10 flex flex-col items-center gap-6 text-center">
            <div className="relative">
              <div className="h-16 w-16 rounded-full bg-violet-500/10 flex items-center justify-center">
                {synthType === "clone"
                  ? <Copy className="h-8 w-8 text-violet-400 animate-pulse" />
                  : <Wand2 className="h-8 w-8 text-violet-400 animate-pulse" />}
              </div>
              <div className="absolute inset-0 rounded-full border-2 border-violet-500/30 animate-spin border-t-violet-400" />
            </div>
            <div>
              <p className="font-semibold text-base text-foreground">{stages[stageIdx]!.label}</p>
              <p className="text-sm text-muted-foreground mt-1">{stages[stageIdx]!.sub}</p>
            </div>
            <div className="flex gap-1.5">
              {stages.map((_, i) => (
                <div
                  key={i}
                  className={`h-1.5 w-8 rounded-full transition-colors ${i <= stageIdx ? "bg-violet-400" : "bg-muted"}`}
                />
              ))}
            </div>
          </div>
        ) : (
          <div className="space-y-5 py-2 overflow-y-auto flex-1">
            {/* Synthesize vs Clone mode toggle */}
            <div className="space-y-1.5">
              <Label className="text-sm font-semibold">Mode</Label>
              <div className="grid grid-cols-2 gap-2">
                <button
                  type="button"
                  data-testid="mode-synthesize"
                  onClick={() => handleSynthTypeChange("synthesize")}
                  className={`rounded-lg border px-3 py-2.5 text-left transition-colors ${synthType === "synthesize" ? "border-violet-500/60 bg-violet-500/10 text-violet-200" : "border-border text-muted-foreground hover:border-border/80 hover:text-foreground"}`}
                >
                  <p className="text-xs font-semibold flex items-center gap-1.5"><Wand2 className="h-3 w-3" /> Synthesize</p>
                  <p className="text-[10px] mt-0.5 opacity-70">Original game inspired by your references</p>
                </button>
                <button
                  type="button"
                  data-testid="mode-clone"
                  onClick={() => handleSynthTypeChange("clone")}
                  className={`rounded-lg border px-3 py-2.5 text-left transition-colors ${synthType === "clone" ? "border-violet-500/60 bg-violet-500/10 text-violet-200" : "border-border text-muted-foreground hover:border-border/80 hover:text-foreground"}`}
                >
                  <p className="text-xs font-semibold flex items-center gap-1.5"><Copy className="h-3 w-3" /> Clone</p>
                  <p className="text-[10px] mt-0.5 opacity-70">Faithful reconstruction of the exact game</p>
                </button>
              </div>
              {synthType === "clone" && (
                <>
                  <p className="text-[10px] text-amber-400/80 flex items-center gap-1 mt-1">
                    ⚡ Clone mode uses a faithful-reproduction prompt — AI will preserve original names, mechanics, and rules.
                  </p>
                  {/* R2: destination toggle for clone mode */}
                  <div className="mt-2">
                    <Label className="text-xs text-muted-foreground mb-1.5 block">Destination</Label>
                    <div className="grid grid-cols-2 gap-2">
                      <button
                        type="button"
                        onClick={() => setCloneDestination("new_project")}
                        className={`rounded-lg border px-3 py-2 text-left text-xs transition-colors ${cloneDestination === "new_project" ? "border-violet-500/60 bg-violet-500/10 text-violet-200" : "border-border text-muted-foreground hover:text-foreground"}`}
                      >
                        <span className="font-semibold block">New project</span>
                        <span className="opacity-70 text-[10px]">Create a separate project for this clone</span>
                      </button>
                      <button
                        type="button"
                        onClick={() => setCloneDestination("populate_current")}
                        className={`rounded-lg border px-3 py-2 text-left text-xs transition-colors ${cloneDestination === "populate_current" ? "border-violet-500/60 bg-violet-500/10 text-violet-200" : "border-border text-muted-foreground hover:text-foreground"}`}
                      >
                        <span className="font-semibold block">Into this project</span>
                        <span className="opacity-70 text-[10px]">Add cloned content into the current project</span>
                      </button>
                    </div>
                  </div>
                </>
              )}
            </div>

            {/* Output mode toggle — only for synthesize mode */}
            {synthType === "synthesize" && (
              <div className="space-y-1.5">
                <Label className="text-sm font-semibold">Output</Label>
                <div className="grid grid-cols-2 gap-2">
                  {workspaceSlug && (
                    <button
                      type="button"
                      onClick={() => setMode("new_project")}
                      className={`rounded-lg border px-3 py-2.5 text-left transition-colors ${mode === "new_project" ? "border-violet-500/60 bg-violet-500/10 text-violet-200" : "border-border text-muted-foreground hover:border-border/80 hover:text-foreground"}`}
                    >
                      <p className="text-xs font-semibold">New project</p>
                      <p className="text-[10px] mt-0.5 opacity-70">Create a brand-new project in this workspace</p>
                    </button>
                  )}
                  <button
                    type="button"
                    onClick={() => setMode("populate_current")}
                    className={`rounded-lg border px-3 py-2.5 text-left transition-colors ${mode === "populate_current" ? "border-violet-500/60 bg-violet-500/10 text-violet-200" : "border-border text-muted-foreground hover:border-border/80 hover:text-foreground"} ${!workspaceSlug ? "col-span-2" : ""}`}
                  >
                    <p className="text-xs font-semibold">Enrich current project</p>
                    <p className="text-[10px] mt-0.5 opacity-70">Add components, rules &amp; players to this project</p>
                  </button>
                </div>
              </div>
            )}

            {/* Game selection */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label className="text-sm font-semibold">
                  {synthType === "clone" ? "Game to clone" : "Synthesize from"}
                </Label>
                {synthType === "synthesize" && (
                  <button
                    onClick={toggleAll}
                    className="text-xs text-primary hover:underline"
                  >
                    {selectedIds.size === researched.length ? "Deselect all" : "Select all"}
                  </button>
                )}
              </div>
              <div className="rounded-lg border border-border divide-y divide-border max-h-48 overflow-y-auto">
                {researched.map((g) => (
                  <label
                    key={g.id}
                    className="flex items-center gap-3 px-3 py-2.5 cursor-pointer hover:bg-muted/50 transition-colors"
                  >
                    {synthType === "clone" ? (
                      <input
                        type="radio"
                        name="clone-game"
                        checked={cloneGameId === g.id}
                        onChange={() => setCloneGameId(g.id)}
                        className="accent-violet-400"
                      />
                    ) : (
                      <Checkbox
                        checked={selectedIds.has(g.id)}
                        onCheckedChange={() => toggleGame(g.id)}
                      />
                    )}
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium truncate">{g.name}</p>
                      {g.gameData?.keyMechanics?.length ? (
                        <p className="text-[11px] text-muted-foreground truncate">
                          {g.gameData.keyMechanics.slice(0, 3).join(" · ")}
                        </p>
                      ) : null}
                    </div>
                  </label>
                ))}
              </div>
              {synthType === "synthesize" && selectedGames.length === 0 && (
                <p className="text-xs text-destructive flex items-center gap-1">
                  <AlertTriangle className="h-3 w-3" /> Select at least one game
                </p>
              )}
              {synthType === "clone" && !cloneGameId && (
                <p className="text-xs text-destructive flex items-center gap-1">
                  <AlertTriangle className="h-3 w-3" /> Select a game to clone
                </p>
              )}
            </div>

            {/* Designer direction / clone notes */}
            <div className="space-y-1.5">
              <Label className="text-sm font-semibold">
                {synthType === "clone" ? "Modifier notes" : "Direction"}{" "}
                <span className="font-normal text-muted-foreground">(optional)</span>
              </Label>
              <Textarea
                value={direction}
                onChange={(e) => setDirection(e.target.value)}
                placeholder={synthType === "clone"
                  ? "e.g. 'Include all official expansions', 'Focus on the base game only', 'Add a note about the revised 2nd edition rules'"
                  : "e.g. 'Focus on asymmetric player powers', 'Make it 30 minutes, family-friendly', 'Lean into the trading mechanic'"}
                className="text-sm min-h-[72px] resize-none"
                maxLength={400}
              />
              {direction.length > 0 && (
                <p className="text-[10px] text-muted-foreground text-right">{direction.length}/400</p>
              )}
            </div>

            {/* Info notice */}
            <div className="rounded-lg border border-violet-500/20 bg-violet-500/5 p-3 text-xs text-violet-200">
              <p className="font-semibold mb-1">How it works</p>
              {synthType === "clone" ? (
                <p className="text-violet-200/70">
                  The AI faithfully reconstructs the selected game using its real component names, official rules text, and accurate player counts and play times — so you can study or modify the exact game.
                </p>
              ) : (
                <p className="text-violet-200/70">
                  The AI studies the design DNA of your selected games — their mechanics, structure, and core loops — then synthesizes an original game that combines their strongest patterns in a fresh way.
                </p>
              )}
            </div>
          </div>
        )}

        {!reversing && (
          <DialogFooter>
            <Button variant="outline" onClick={onClose}>Cancel</Button>
            <Button
              className="gap-2 bg-violet-600 hover:bg-violet-700"
              onClick={run}
              disabled={synthType === "clone" ? !cloneGameId : selectedGames.length === 0}
            >
              {synthType === "clone"
                ? <><Copy className="h-4 w-4" /> Clone Game <ArrowRight className="h-4 w-4" /></>
                : <><Wand2 className="h-4 w-4" /> Reverse Engineer <ArrowRight className="h-4 w-4" /></>
              }
            </Button>
          </DialogFooter>
        )}
      </DialogContent>
    </Dialog>
  );
}

/* ── InspirationShelf ────────────────────────────────────────────────── */

function mapDbToRefGame(row: {
  id: number; name: string; borrowing?: string | null; avoiding?: string | null;
  researchId?: number | null; gameData?: Record<string, unknown> | null;
}): RefGame {
  return {
    id: String(row.id),
    name: row.name,
    borrowing: row.borrowing ?? "",
    avoiding: row.avoiding ?? "",
    researchId: row.researchId ?? undefined,
    gameData: (row.gameData as GameData | undefined) ?? undefined,
  };
}

function InspirationShelf({ projectId, workspaceSlug }: { projectId: number; workspaceSlug?: string }) {
  const { data: project } = useGetProject(projectId);
  const qc = useQueryClient();
  const { toast } = useToast();
  const [, setLocation] = useLocation();

  const { data: dbRefGames = [] } = useListReferenceGames(projectId);
  const createRefGame = useCreateReferenceGame();
  const deleteRefGame = useDeleteReferenceGame();
  const updateRefGame = useUpdateReferenceGame();

  const [localOrder, setLocalOrder] = useState<RefGame[]>([]);
  const [draft, setDraft] = useState({ name: "", borrowing: "", avoiding: "" });
  const [showForm, setShowForm] = useState(false);
  const [lookingUp, setLookingUp] = useState<string | null>(null);
  const [showReverseDialog, setShowReverseDialog] = useState(false);
  const [preselectedGameId, setPreselectedGameId] = useState<string | null>(null);
  const [dialogSynthType, setDialogSynthType] = useState<"synthesize" | "clone">("synthesize");
  const [findingSimilar, setFindingSimilar] = useState(false);
  const [similarGames, setSimilarGames] = useState<string[]>([]);
  const [showSimilarDialog, setShowSimilarDialog] = useState(false);

  useEffect(() => {
    setLocalOrder(dbRefGames.map(mapDbToRefGame));
  }, [dbRefGames]);

  const refGames = localOrder;

  const addGame = () => {
    if (!draft.name.trim()) return;
    createRefGame.mutate(
      { projectId, data: { name: draft.name.trim(), borrowing: draft.borrowing || undefined, avoiding: draft.avoiding || undefined } },
      {
        onSuccess: () => {
          qc.invalidateQueries({ queryKey: getListReferenceGamesQueryKey(projectId) });
          setDraft({ name: "", borrowing: "", avoiding: "" });
          setShowForm(false);
        },
        onError: () => toast({ title: "Failed to add game", variant: "destructive" }),
      },
    );
  };

  const removeGame = (id: string) => {
    const numId = Number(id);
    setLocalOrder((prev) => prev.filter((g) => g.id !== id));
    deleteRefGame.mutate(
      { projectId, referenceGameId: numId },
      {
        onSuccess: () => qc.invalidateQueries({ queryKey: getListReferenceGamesQueryKey(projectId) }),
        onError: () => {
          qc.invalidateQueries({ queryKey: getListReferenceGamesQueryKey(projectId) });
          toast({ title: "Failed to remove game", variant: "destructive" });
        },
      },
    );
  };

  const handleReorder = (next: RefGame[]) => {
    setLocalOrder(next);
    const patches = next.map((g, idx) =>
      new Promise<void>((resolve, reject) =>
        updateRefGame.mutate(
          { projectId, referenceGameId: Number(g.id), data: { position: idx } },
          { onSuccess: () => resolve(), onError: (err) => reject(err) },
        )
      )
    );
    Promise.all(patches).catch(() => {
      qc.invalidateQueries({ queryKey: getListReferenceGamesQueryKey(projectId) });
    });
  };

  const lookUpGame = async (id: string, depth = "comprehensive", clearExisting = false) => {
    const game = refGames.find((g) => g.id === id);
    if (!game) return;
    setLookingUp(id);
    if (clearExisting) {
      setLocalOrder((prev) => prev.map((g) => g.id === id ? { ...g, gameData: undefined, researchId: undefined } : g));
    }
    try {
      const res = await fetch(`${apiBase()}/api/projects/${projectId}/research/game-lookup`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({ gameName: game.name, borrowing: game.borrowing, avoiding: game.avoiding, depth, referenceGameId: Number(id) }),
      });
      if (!res.ok) throw new Error(await res.text());
      const { research, gameData } = await res.json() as { research: { id: number }; gameData: GameData };
      qc.invalidateQueries({ queryKey: getListReferenceGamesQueryKey(projectId) });
      qc.invalidateQueries({ queryKey: getListResearchQueryKey(projectId) });
      toast({ title: `${game.name} researched`, description: "Full breakdown saved to your notes." });
    } catch (err) {
      toast({ title: "Lookup failed", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
    } finally {
      setLookingUp(null);
    }
  };

  const findSimilarGames = async () => {
    if (!project) return;
    setFindingSimilar(true);
    try {
      const res = await fetch(`${apiBase()}/api/projects/${projectId}/research/similar-games`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify({
          gameName: project.name,
          description: project.description,
          gameType: project.gameType,
          genre: project.genre,
          playerCount: project.playerCount,
        }),
      });
      if (!res.ok) throw new Error(await res.text());
      const { games } = await res.json() as { games: string[] };
      setSimilarGames(games);
      setShowSimilarDialog(true);
      toast({ title: "Similar games found", description: `Found ${games.length} games similar to your project.` });
    } catch (err) {
      toast({ title: "Could not find similar games", description: err instanceof Error ? err.message : String(err), variant: "destructive" });
    } finally {
      setFindingSimilar(false);
    }
  };

  const addSimilarGame = (gameName: string) => {
    createRefGame.mutate(
      { projectId, data: { name: gameName } },
      {
        onSuccess: () => {
          qc.invalidateQueries({ queryKey: getListReferenceGamesQueryKey(projectId) });
          setSimilarGames((prev) => prev.filter((g) => g !== gameName));
          toast({ title: "Game added", description: `${gameName} added to your research list.` });
        },
        onError: () => toast({ title: "Failed to add game", variant: "destructive" }),
      },
    );
  };

  const researched = refGames.filter((g) => g.gameData);

  return (
    <div className="space-y-4">
      {/* Section header */}
      <div className="flex items-center justify-between gap-3 flex-wrap">
        <div>
          <h3 className="font-semibold text-base flex items-center gap-2">
            <Heart className="h-4 w-4 text-rose-400" /> Games that shaped your vision
          </h3>
          <p className="text-xs text-muted-foreground mt-0.5">
            Add a game, hit <span className="text-primary font-medium">Research with AI</span> to pull comprehensive details from all sources, then{" "}
            <span className="text-violet-400 font-medium">Reverse Engineer</span> to recreate the exact game with all components.
          </p>
        </div>
        <div className="flex gap-2">
          <Button
            size="sm"
            variant="outline"
            className="gap-1.5 shrink-0 border-primary/30 text-primary hover:bg-primary/10"
            onClick={findSimilarGames}
            disabled={findingSimilar || !project}
          >
            {findingSimilar ? <Loader2 className="h-3.5 w-3.5 animate-spin" /> : <Sparkles className="h-3.5 w-3.5" />}
            Find similar games
          </Button>
          {researched.length >= 1 && workspaceSlug && (
            <Button
              size="sm"
              variant="outline"
              className="gap-1.5 shrink-0 border-violet-500/30 text-violet-400 hover:bg-violet-500/10"
              onClick={() => { setDialogSynthType("synthesize"); setPreselectedGameId(null); setShowReverseDialog(true); }}
            >
              <Wand2 className="h-3.5 w-3.5" />
              Reverse Engineer all
            </Button>
          )}
          {!showForm && (
            <Button size="sm" variant="outline" className="gap-1.5 shrink-0" onClick={() => setShowForm(true)}>
              <Plus className="h-3.5 w-3.5" /> Add a game
            </Button>
          )}
        </div>
      </div>

      {/* Add game form */}
      {showForm && (
        <div className="rounded-xl border border-primary/30 bg-primary/5 p-4 space-y-3">
          <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Add a reference game</p>
          <Input
            placeholder="Game name (e.g. Wingspan, Catan, Dominion…)"
            value={draft.name}
            onChange={(e) => setDraft((d) => ({ ...d, name: e.target.value }))}
            autoFocus
            onKeyDown={(e) => e.key === "Enter" && addGame()}
          />
          <Input
            placeholder="What's the best part you want to borrow? (optional)"
            value={draft.borrowing}
            onChange={(e) => setDraft((d) => ({ ...d, borrowing: e.target.value }))}
          />
          <Input
            placeholder="What would you do differently? (optional)"
            value={draft.avoiding}
            onChange={(e) => setDraft((d) => ({ ...d, avoiding: e.target.value }))}
          />
          <div className="flex gap-2 pt-1">
            <Button size="sm" onClick={addGame} disabled={!draft.name.trim()}>Add game</Button>
            <Button size="sm" variant="ghost" onClick={() => setShowForm(false)}>Cancel</Button>
          </div>
        </div>
      )}

      {/* Drag-and-drop list */}
      {refGames.length > 0 && (
        <Reorder.Group
          axis="y"
          values={refGames}
          onReorder={handleReorder}
          className="space-y-3"
          as="div"
        >
          {refGames.map((rg) => (
            <DraggableGameCard
              key={rg.id}
              game={rg}
              onRemove={() => removeGame(rg.id)}
              onResearch={(depth) => lookUpGame(rg.id, depth)}
              onReResearch={() => lookUpGame(rg.id, undefined, true)}
              onReverseEngineer={(gid) => { setDialogSynthType("synthesize"); setPreselectedGameId(gid); setShowReverseDialog(true); }}
              onClone={(gid) => { setDialogSynthType("clone"); setPreselectedGameId(gid); setShowReverseDialog(true); }}
              researching={lookingUp === rg.id}
              canReverseEngineer={Boolean(workspaceSlug && rg.gameData)}
            />
          ))}
        </Reorder.Group>
      )}

      {/* Empty state */}
      {refGames.length === 0 && !showForm && (
        <button
          onClick={() => setShowForm(true)}
          className="w-full rounded-xl border-2 border-dashed border-border hover:border-primary/40 p-8 text-center text-muted-foreground hover:text-foreground transition-colors group"
        >
          <Heart className="h-8 w-8 mx-auto mb-2 opacity-30 group-hover:opacity-60 transition-opacity" />
          <p className="text-sm">Add the games that inspired you</p>
          <p className="text-xs mt-1 opacity-60">Every great game designer knows their influences</p>
        </button>
      )}

      {/* Full reverse engineer / clone dialog */}
      <ReverseEngineerDialog
        open={showReverseDialog}
        onClose={() => setShowReverseDialog(false)}
        researched={researched}
        projectId={projectId}
        workspaceSlug={workspaceSlug}
        preselectedGameId={preselectedGameId}
        initialSynthType={dialogSynthType}
        onSuccess={(result) => {
          const isClone = result.synthType === "clone";
          if (result.workspaceSlug) {
            toast({
              title: isClone ? "Game cloned!" : "Game reverse engineered!",
              description: isClone
                ? `${result.project.name} has been faithfully reconstructed with all real components and rules.`
                : `${result.project.name} recreated with all components and rules`,
            });
            setLocation(`/${result.workspaceSlug}/${result.project.slug ?? result.project.id}`);
          } else {
            qc.invalidateQueries();
            toast({
              title: isClone ? "Game cloned!" : "Game reverse engineered!",
              description: isClone
                ? "All real components and rules have been reconstructed."
                : "All components and rules have been recreated.",
            });
          }
        }}
      />

      {/* Similar games dialog */}
      <Dialog open={showSimilarDialog} onOpenChange={setShowSimilarDialog}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Sparkles className="h-5 w-5 text-primary" />
              Games similar to your project
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-3 py-2">
            <p className="text-sm text-muted-foreground">
              Based on your project's characteristics, here are similar games you might want to research:
            </p>
            {similarGames.length === 0 ? (
              <p className="text-sm text-muted-foreground text-center py-4">No similar games found.</p>
            ) : (
              <div className="space-y-2 max-h-64 overflow-y-auto">
                {similarGames.map((gameName) => (
                  <div
                    key={gameName}
                    className="flex items-center justify-between p-3 rounded-lg border bg-card hover:bg-card/80 transition-colors"
                  >
                    <span className="text-sm font-medium">{gameName}</span>
                    <Button
                      size="sm"
                      variant="outline"
                      className="gap-1.5 text-xs h-7"
                      onClick={() => addSimilarGame(gameName)}
                    >
                      <Plus className="h-3 w-3" /> Add
                    </Button>
                  </div>
                ))}
              </div>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowSimilarDialog(false)}>Close</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

function GamesToKnow({ projectId }: { projectId: number }) {
  const [games, setGames] = useState<CompGame[]>(() => loadComp(projectId));
  const [confirmDelete, setConfirmDelete] = useState<string | null>(null);

  const persist = (next: CompGame[]) => { setGames(next); saveComp(projectId, next); };

  const add = () => {
    const g: CompGame = {
      id: crypto.randomUUID(), game: "", players: "", duration: "",
      complexity: 3, funFactor: 7, loveAbout: "", wouldDoBetter: "", notes: "",
    };
    persist([...games, g]);
  };

  const upd = (id: string, u: Partial<CompGame>) =>
    persist(games.map((g) => (g.id === id ? { ...g, ...u } : g)));

  const del = (id: string) => persist(games.filter((g) => g.id !== id));

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="font-semibold text-base flex items-center gap-2">
            <TrendingUp className="h-4 w-4 text-blue-400" /> Games to know
          </h3>
          <p className="text-xs text-muted-foreground mt-0.5">
            Study what's already out there — so you can stand apart from it.
          </p>
        </div>
        <Button size="sm" variant="outline" className="gap-1.5" onClick={add}>
          <Plus className="h-3.5 w-3.5" /> Add a game
        </Button>
      </div>

      {games.length === 0 && (
        <button
          onClick={add}
          className="w-full rounded-xl border-2 border-dashed border-border hover:border-primary/40 p-8 text-center text-muted-foreground hover:text-foreground transition-colors group"
        >
          <TrendingUp className="h-8 w-8 mx-auto mb-2 opacity-30 group-hover:opacity-60 transition-opacity" />
          <p className="text-sm">Track games in your market</p>
          <p className="text-xs mt-1 opacity-60">Know what you're up against</p>
        </button>
      )}

      <div className="space-y-3">
        {games.map((g) => (
          <div key={g.id} className="rounded-xl border border-border bg-card p-4 space-y-3 group">
            <div className="flex items-start gap-2">
              <div className="flex-1 grid grid-cols-1 sm:grid-cols-3 gap-2">
                <Input
                  className="h-8 text-sm font-medium"
                  value={g.game}
                  onChange={(e) => upd(g.id, { game: e.target.value })}
                  placeholder="Game title"
                />
                <Input
                  className="h-8 text-sm"
                  value={g.players}
                  onChange={(e) => upd(g.id, { players: e.target.value })}
                  placeholder="Players (e.g. 2–5)"
                />
                <Input
                  className="h-8 text-sm"
                  value={g.duration}
                  onChange={(e) => upd(g.id, { duration: e.target.value })}
                  placeholder="Play time (e.g. 60 min)"
                />
              </div>
              {confirmDelete === g.id ? (
                <div className="flex items-center gap-1 shrink-0">
                  <span className="text-[11px] text-destructive font-medium whitespace-nowrap">Remove?</span>
                  <Button size="icon" variant="ghost" className="h-8 w-8 text-destructive hover:bg-destructive/10" onClick={() => { del(g.id); setConfirmDelete(null); }}>
                    <Check className="h-3.5 w-3.5" />
                  </Button>
                  <Button size="icon" variant="ghost" className="h-8 w-8 text-muted-foreground" onClick={() => setConfirmDelete(null)}>
                    <X className="h-3.5 w-3.5" />
                  </Button>
                </div>
              ) : (
                <Button
                  size="icon" variant="ghost"
                  className="h-8 w-8 shrink-0 text-muted-foreground/40 hover:text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity"
                  onClick={() => setConfirmDelete(g.id)}
                  title="Remove this game"
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </Button>
              )}
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1">
                <div className="flex items-center justify-between">
                  <span className="text-xs text-muted-foreground">How heavy is it?</span>
                  <span className="text-xs font-medium text-foreground">{COMPLEXITY_LABELS[g.complexity] ?? g.complexity}</span>
                </div>
                <input
                  type="range" min={1} max={5} step={1}
                  value={g.complexity}
                  onChange={(e) => upd(g.id, { complexity: parseInt(e.target.value) })}
                  className="w-full accent-primary h-1.5"
                />
              </div>
              <div className="space-y-1">
                <div className="flex items-center justify-between">
                  <span className="text-xs text-muted-foreground">Fun factor</span>
                  <span className="text-xs font-medium text-foreground">{g.funFactor}/10</span>
                </div>
                <input
                  type="range" min={1} max={10} step={1}
                  value={g.funFactor}
                  onChange={(e) => upd(g.id, { funFactor: parseInt(e.target.value) })}
                  className="w-full accent-primary h-1.5"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
              <Input
                className="h-8 text-sm"
                value={g.loveAbout}
                onChange={(e) => upd(g.id, { loveAbout: e.target.value })}
                placeholder="What makes it great?"
              />
              <Input
                className="h-8 text-sm"
                value={g.wouldDoBetter}
                onChange={(e) => upd(g.id, { wouldDoBetter: e.target.value })}
                placeholder="Where could it be better?"
              />
            </div>

            {(g.loveAbout || g.wouldDoBetter || g.notes) && (
              <Textarea
                rows={2}
                className="text-sm resize-none"
                value={g.notes}
                onChange={(e) => upd(g.id, { notes: e.target.value })}
                placeholder="Any other notes..."
              />
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

