389	  // ──────────────────────────────────────────────────────────────────────────
390	  // Drag-and-drop reorder
391	  // ──────────────────────────────────────────────────────────────────────────
392	  const handleDragStart = (e: React.DragEvent, ruleId: number) => {
393	    setDraggedId(ruleId);
394	    e.dataTransfer.effectAllowed = "move";
395	    // Some browsers require setData for drag to start
396	    try { e.dataTransfer.setData("text/plain", String(ruleId)); } catch { /* noop */ }
397	  };
