399	  const handleDragOver = (e: React.DragEvent, overId: number, sectionKey: string) => {
400	    if (draggedId === null || draggedId === overId) return;
401	    e.preventDefault();
402	    e.dataTransfer.dropEffect = "move";
403	    const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
404	    const before = e.clientY - rect.top < rect.height / 2;
405	    setDropTargetId(overId);
406	    setInsertBefore(before);
407	    dropSectionRef.current = sectionKey;
408	  };
409	
410	  const handleDragEnd = () => {
411	    setDraggedId(null);
412	    setDropTargetId(null);
413	    dropSectionRef.current = null;
414	  };
