416	  const handleDrop = async () => {
417	    const dragged = draggedId;
418	    const target = dropTargetId;
419	    const before = insertBefore;
420	    const targetSection = dropSectionRef.current;
421	    handleDragEnd();
422	    if (dragged === null || target === null || dragged === target || !rules) return;
423	
424	    const ordered = [...rules].sort((a, b) => {
425	      const ao = a.displayOrder ?? 0;
426	      const bo = b.displayOrder ?? 0;
427	      if (ao !== bo) return ao - bo;
428	      return a.id - b.id;
429	    });
430	    const fromIdx = ordered.findIndex((r) => r.id === dragged);
431	    const toIdx = ordered.findIndex((r) => r.id === target);
432	    if (fromIdx === -1 || toIdx === -1) return;
433	
434	    const [moved] = ordered.splice(fromIdx, 1);
435	    let insertAt = ordered.findIndex((r) => r.id === target);
436	    if (!before) insertAt += 1;
