1290	// ────────────────────────────────────────────────────────────────────────────
1291	// Auto-link "Rule #N" / "Rule N" / "rule N" references inside content.
1292	// Only links when the referenced rule actually exists in this project.
1293	// ────────────────────────────────────────────────────────────────────────────
1294	const RULE_REF_REGEX = /\b(Rule|rule|RULE)\s*#?\s*(\d+)\b/g;
1295	
1296	function renderRuleContentWithLinks(
1297	  content: string,
1298	  ruleById: Map<number, Rule>,
1299	  onClick: (id: number) => void,
1300	  selfId: number,
1301	): React.ReactNode[] {
1302	  if (!content) return [content];
1303	  const out: React.ReactNode[] = [];
1304	  let lastIndex = 0;
1305	  let match: RegExpExecArray | null;
1306	  RULE_REF_REGEX.lastIndex = 0;
1307	  let key = 0;
1308	  while ((match = RULE_REF_REGEX.exec(content)) !== null) {
1309	    const id = parseInt(match[2], 10);
1310	    const target = ruleById.get(id);
1311	    // Only link if target exists and isn't the same rule (no self-loops)
1312	    if (!target || id === selfId) continue;
1313	    if (match.index > lastIndex) out.push(content.slice(lastIndex, match.index));
1314	    out.push(
1315	      <button
1316	        key={`rl-${key++}-${match.index}`}
1317	        type="button"
1318	        onClick={(e) => { e.stopPropagation(); onClick(id); }}
1319	        className="inline-flex items-center gap-0.5 text-primary hover:text-primary/80 hover:underline font-medium px-0.5 py-0 rounded"
1320	        title={target.title}
1321	        data-testid={`rule-link-${id}`}
1322	      >
1323	        {match[0]}
1324	      </button>,
1325	    );
1326	    lastIndex = match.index + match[0].length;
1327	  }
1328	  if (lastIndex < content.length) out.push(content.slice(lastIndex));
1329	  return out.length > 0 ? out : [content];
1330	}
