                      </Button>
                    </div>
                  </div>
                </DialogContent>
              </Dialog>
            )}
          </>
        )}

        {game.researchId && !hasData && (
          <span className="ml-auto inline-flex items-center gap-1 text-[10px] text-muted-foreground">
