toolUseResult.newString:
{game.gameData.keyMechanics?.length ? (
  <div>
    <p className="text-[10px] uppercase tracking-wider font-semibold text-muted-foreground mb-2">Key mechanics</p>
    <div className="flex flex-wrap gap-1.5">
      {game.gameData.keyMechanics.map((m, mi) => {
        const mechKey = `${game.name}::${m}`;
        const isLoading = usingMechanic === mechKey;
        return (
          <div key={mi} className="flex items-center gap-1">
            <span className="text-xs bg-primary/10 border border-primary/20 text-primary px-2 py-0.5 rounded-full">{m}</span>
            <button
              onClick={() => onUseMechanic(m, game.name)}
              disabled={isLoading || usingMechanic !== null}
              className="text-[10px] bg-emerald-500/15 border border-emerald-500/30 text-emerald-400 hover:bg-emerald-500/25 px-1.5 py-0.5 rounded-full transition-colors disabled:opacity-40 flex items-center gap-0.5 whitespace-nowrap"
              title={`Import "${m}" as a draft rule in the Rules tab`}
            >
              {isLoading
                ? <><Loader2 className="h-2.5 w-2.5 animate-spin" /> importing…</>
                : <><Plus className="h-2.5 w-2.5" /> Use this</>}
            </button>
          </div>
        );
      })}
    </div>
  </div>
) : null}

