const handleUseMechanic = async (mechanicName: string, gameName: string) => {
  const key = `${gameName}::${mechanicName}`;
  setUsingMechanic(key);
  try {
    const parsed = await parseMechanic(projectId, mechanicName, gameName);
    const rule = await createRuleMut.mutateAsync({
      projectId,
      data: {
        title: `[Placeholder] From ${gameName}: ${mechanicName}`,
        content: parsed.content,
        category: "imported",
        priority: 2,
        designNotes: `Imported from ${gameName}.${parsed.designNotes ? " " + parsed.designNotes : ""}`,
      },
    });
    await createTaskMut.mutateAsync({
      projectId,
      data: {
        title: `Implement "${mechanicName}" from ${gameName}`,
        description: `Draft rule created (Rule #${rule.id}). Review and finalize the "${mechanicName}" mechanic adapted from ${gameName}.`,
        status: "todo",
        priority: "medium",
