const playtestTotal     = (stats as { playtestCount?: number } | undefined)?.playtestCount ?? 0;
const playtestScheduled = nextPlaytest.date && new Date(nextPlaytest.date) > new Date() ? 1 : 0;

const balanceScore   = balanceReport?.balanceScore ?? null;
const balanceVerdict = balanceReport?.verdict ?? "";

const statusScoreLabel = balanceScore === null
  ? "—"
  : balanceScore >= 80 ? "Excellent"
  : balanceScore >= 65 ? "Good"
  : balanceScore >= 45 ? "Fair"
  : "Needs work";

const statusScoreColor = balanceScore === null
  ? "text-muted-foreground"
  : balanceScore >= 80 ? "text-emerald-400"
  : balanceScore >= 65 ? "text-lime-400"
  : balanceScore >= 45 ? "text-amber-400"
  : "text-red-400";

/* Compute the single highest-priority "next step" */
const nextStep = useMemo<{ label: string; action: "playtest" | "none" }>(() => {
  if (activeByCol.blocker.length > 0)
    return { label: `Resolve ${activeByCol.blocker.length} critical design blocker${activeByCol.blocker.length > 1 ? "s" : ""}`, action: "none" };
  if (entityTotal === 0)
    return { label: "Define your first component in the Ontology tab", action: "none" };
  if (ruleTotal === 0)
    return { label: "Write your first rule in the Rules tab", action: "none" };
  if (playerTotal === 0)
    return { label: "Define player roles in the Players tab", action: "none" };
  if (playtestScheduled === 0)
    return { label: "Schedule your next playtest session", action: "playtest" };
  if (balanceScore !== null && balanceScore < 50)
    return { label: "Balance score is low — review entity stats", action: "none" };
  if (experimentalRules > 0)
    return { label: `Stabilise ${experimentalRules} experimental rule${experimentalRules > 1 ? "s" : ""}`, action: "none" };
  return { label: "Looking good — consider advancing to the next design phase", action: "none" };
}, [activeByCol.blocker.length, entityTotal, ruleTotal, playerTotal, playtestScheduled, balanceScore, experimentalRules]);

const scrollToPlaytest = () => {
  playtestCardRef.current?.scrollIntoView({ behavior: "smooth", block: "center" });
  setTimeout(() => {
    const input = playtestCardRef.current?.querySelector<HTMLInputElement>("input[type='date']");
    input?.focus();
  }, 400);
};

const radarData = FINGERPRINT_AXES.map((ax) => ({
  subject: ax.charAt(0).toUpperCase() + ax.slice(1),
  value: fingerprint[ax],
}));

const currentPhaseIdx = PHASE_INDEX[form.designPhase] ?? 0;
const currentPhase    = DESIGN_PHASES[currentPhaseIdx];
const playtestDate    = nextPlaytest.date;
const daysAway        = playtestDate ? daysUntil(playtestDate) : null;

if (projectLoading) {
  return <div className="space-y-4 pb-8"><Skeleton className="h-32 w-full" /><Skeleton className="h-64 w-full" /></div>;
}

return (
  <div className="space-y-6 pb-10">

    {/* ═══════════════════════════════════════════════════════════════
        GAME IDENTITY VIEW — hero card + Game Bible (own tab)
        ═══════════════════════════════════════════════════════════════ */}
    {view === "identity" && (
      <Card className="border-primary/20 bg-gradient-to-br from-primary/5 to-transparent">
        <CardHeader className="py-3 px-5 border-b border-border/50">
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm font-semibold">Game Identity</CardTitle>
            <SaveIndicator status={sectionSaveStatus.hero} />
          </div>
        </CardHeader>
        <CardContent className="pt-5 pb-5 space-y-4">
          <div className="space-y-3">
            <div>
              <Label className="text-xs text-muted-foreground mb-1 block">Elevator pitch</Label>
              <Textarea
                placeholder="In one or two sentences, what's the core experience of your game?"
                rows={2}
                className="resize-none text-sm bg-background/60"
                value={heroMeta.elevatorPitch || ""}

    GAME DASHBOARD VIEW — phase / glance / recent / fingerprint / complexity
    ═══════════════════════════════════════════════════════════════ */}
{view === "dashboard" && (
  <>
    {/* Row 1: Design Phase (left) | Project at a Glance (right) */}
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
      {/* Design Phase tracker */}
      <Card>
        <CardHeader className="border-b border-border py-3 px-4 flex-row items-center gap-2">
          <Flag className="w-4 h-4 text-primary shrink-0" />
          <div className="flex-1 min-w-0">
            <CardTitle className="text-sm font-semibold">Design Phase</CardTitle>
          </div>
          <SaveIndicator status={sectionSaveStatus.phase} />
          <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-full border shrink-0 ${currentPhase?.color}`}>
            {currentPhase?.label}
          </span>
        </CardHeader>
        <CardContent className="px-4 py-3 space-y-2">
          <div className="flex flex-col gap-1">
            {DESIGN_PHASES.map((p) => (
              <button
                key={p.value}
                onClick={() => saveDesignPhase(p.value)}
                className={`text-left px-2.5 py-1.5 rounded-md border text-xs font-medium transition-all ${
                  form.designPhase === p.value
                    ? `${p.color} ring-1 ring-current`
                    : "border-transparent text-muted-foreground hover:border-border hover:text-foreground"
                }`}
              >
                <span className="font-semibold">{p.label}</span>
                <span className="ml-1 opacity-60 font-normal">{p.desc}</span>
              </button>
            ))}
          </div>
          <div className="h-1 bg-muted rounded-full overflow-hidden">
            <div className="h-full bg-primary rounded-full transition-all duration-500"
              style={{ width: `${((currentPhaseIdx + 1) / DESIGN_PHASES.length) * 100}%` }} />
          </div>
        </CardContent>
      </Card>

      {/* Project at a Glance */}
      <Card>
        <CardHeader className="border-b border-border py-3 px-4 flex-row items-center gap-2">
          <LayoutDashboard className="w-4 h-4 text-primary shrink-0" />
          <div className="flex-1 min-w-0">
            <CardTitle className="text-sm font-semibold">Project at a Glance</CardTitle>
          </div>
        </CardHeader>
        <CardContent className="px-4 py-3">
          {visibleStats.length > 0 ? (
            <div className="grid grid-cols-3 gap-2">
              {visibleStats.map((stat) => {
                const Icon = stat.Icon;
                return (
                  <div key={stat.label} className={`rounded-lg border border-border p-2 ${stat.bg}`}>
                    <Icon className={`h-3.5 w-3.5 ${stat.color} mb-1`} />
                    <div className="text-lg font-bold leading-none">{statsLoading ? "·" : stat.count}</div>
                    <div className="text-[9px] text-muted-foreground mt-0.5">{stat.label}</div>
                  </div>
                );
              })}
            </div>
          ) : (
            <p className="text-xs text-muted-foreground text-center py-4 italic">
              Add components, rules, or players to see project stats here.
            </p>
          )}
        </CardContent>
      </Card>
    </div>

    {/* Row 2: Game Status Widget + Design Advisor */}
    <div className="space-y-3">
      <GameStatusWidget
        entityTotal={entityTotal}
        entityPct={entityPct}
        ruleTotal={ruleTotal}
        experimentalRules={experimentalRules}

